  var META = {"id":"workover-duration-ts","sceneId":"wo5","title":"从历史工单到可承诺工期：分位数回归 + 蒙特卡洛"};
  var DEMO = {"mode":"auto","html":"demo/index.html","js":"demo/demo.js","label":"可运行示范","intro":"调井深、故障类型、磨铣/压井与计划工期，看五段流水线怎样从 1450 井次工单走到一条可承诺的日期：质控剔除 → 9 维特征 → 21 组分位数回归现场训练（损失曲线、P50 校准、P10—P90 覆盖）→ 2000 次蒙特卡洛合成 → 计划滑杆与 P80 承诺；再点「采纳 P80 承诺 / 人工上调 1 天」看回写怎么记。","height":1160};
  var FILES = [{"name":"README.txt","size":5916,"mime":"text/plain","enc":"text","data":"从历史工单到可承诺工期：分位数回归 + 蒙特卡洛 · 案例包\n================================================\n\n这是什么\n--------\n一个可以直接上传到「石油勘探开发智能化可能性地图」网站的完整案例包：\n讲解内容在 case.json，可运行的五段 AI 作业流在 demo/ 文件夹里。\n\n绑定场景\n--------\n修井 / 工期预测（场景 id：wo5；方法标签：ts）\n\n示范内容：一条可运行的 AI 作业流\n--------------------------------\n调井深、故障类型、磨铣/压井与计划工期，看五段流水线怎样从 1450 井次工单走到一条可承诺的日期：质控剔除 → 9 维特征 → 21 组分位数回归现场训练（损失曲线、P50 校准、P10—P90 覆盖）→ 2000 次蒙特卡洛合成 → 计划滑杆与 P80 承诺；再点「采纳 P80 承诺 / 人工上调 1 天」看回写怎么记。\n\n01 工单采集与质控\n   从作业管理系统导出 1450 井次 × 7 道工序的时效记录，先过三道质控：耗时为负/为零或工序顺序异常（47 条）、7 道工序缺段（51 条）、总工期被系统在 2.6 天截断（30 条）。不合格工单既不进训练集，也不进验证集。\n   产出：得到 1322 井次可用样本（91.2%），按 80/20 划分 1058 训练 / 264 验证。\n   边界：截断工单最容易被忽略：系统在收尾时把总工期压到 2.6 天，如果留在训练集，模型会学会「所有井都很快」，P50 被系统性拉低。\n\n02 特征：模型看到什么\n   把每张工单压成 9 维：井深（km）、5 类故障 one-hot（落物打捞 / 套管整形 / 找堵水 / 冲砂防砂，断脱为基准）、作业复杂度（磨铣 0.6 + 压井 0.4）、工序数（7—9）、含打捞 / 套管 / 磨铣 / 压井。用训练集均值与标准差标准化。\n   产出：模型能解释「同样的故障，深井为什么比浅井多 1—2 天」「磨铣与压井各把哪几道工序拉长」。\n   边界：作业队、天气、设备型号不要直接进模型：它们会随台账变动，模型会突然失准；更稳的做法是分组建模或只用来做后校准。\n\n03 工序级分位数回归\n   对 7 道工序分别拟合 P10 / P50 / P90 三组线性分位数回归，损失函数是 pinball loss；特征标准化后梯度下降 200 轮，留出 264 井次验证。分位数交叉按单调性后处理，输出每道工序的区间。\n   产出：21 组模型在本页现场训练：P10—P90 覆盖率 80.0%（名义 80%），P50 工序中位绝对误差 0.15 天，5 桶校准的预测/实际中位基本落在 45° 线上。\n   边界：分位数交叉（P10 > P50）在小样本工序上很常见，必须做单调性后处理；另外线性模型对井深与故障的交互只能近似，别把系数当成因果效应。\n\n04 蒙特卡洛合成总工期\n   每道工序用 P10/P50/P90 拟合对数正态（σ = (lnP90 − lnP10) / 2.563），按工序依赖顺序抽 2000 组相加；工序之间用共同因子 z_p = 0.60·z₀ + 0.80·ε_p 保留相关性，z₀ 代表地层、队伍、设备的共同扰动。\n   产出：输出总工期 P10 / P50 / P90、按期概率与方差贡献最大的工序；本示范默认井况 P50 = 9.9 天、P90 = 14.9 天，打捞/磨铣贡献约 77% 的方差。\n   边界：忽略工序间相关性会低估总工期方差：本示范里独立抽样的 P10—P90 宽度只有 5.8 天，相关抽样是 7.8 天，覆盖率会从 80% 掉到 60% 以下。\n\n05 计划决策与回写\n   调度拖动计划工期滑杆，看「按 X 天报计划 → 按期 Y%」；常用 P80 作为承诺档，避免把 P50 当承诺。人工确认或改期后回写台账，下一轮重训进入训练集；每月统计实际落在区间内的比例与方差贡献最大的工序。\n   产出：默认井况计划 10 天按期 51%，P80 = 12.9 天覆盖约 80%；现场口径 P80 兑现率 62% → 81%，计划编制 2 h → 10 min，待机/窝工成本 −18%（示范口径）。\n   边界：只用「落在区间外」的井复盘不够，还要看「区间宽度是否随数据积累在收窄」——那才是模型真的在进步的证据；另外 P80 承诺兑现率要按同一口径统计，不能只挑顺利的井。\n\n模型与数据门槛\n----------------\n- 任务类型：分位数回归 + 蒙特卡洛（7 道工序 × 3 个分位，输出区间与按期概率——不是单点工期）\n- 数据门槛：1000+ 井次工序级时效记录（井深、故障类型、7 道工序起止时间；缺工序或截断工单必须先剔除）\n- 可见收益：P80 兑现率 62% → 81%（人工 MAPE 28% → 14%，计划编制 2 h → 10 min（示范口径））\n- 难度：中（工序口径统一与相关性建模是卡点，不是算法）\n\n本案例的核心指标\n----------------\n- 时效记录：1450 井次\n- 工序数：7\n- 验证覆盖：80.0%\n- P80 兑现率：62% → 81%\n\n注意：示范页里的训练/验证指标由浏览器现场计算，使用合成数据；\n现场口径在案例页的「怎么算做对了」里单独列出，两者不能混用。\n\n怎么用\n------\n1. 打开网站，点右上角「＋ 添加案例」；\n2. 把本文件夹（workover-duration-ts）整个拖进弹窗，或点「选择文件夹」；\n3. 右侧逐项校验，全绿后点「校验并添加」；\n4. 页面自动跳到对应场景，三个 tab 立即出现。\n\n文件清单\n--------\n  case.json          清单：元信息 + 专业背景 + 案例流程\n  demo/index.html    示范页（整页模式，沙箱 iframe 中运行）\n  demo/demo.css      示范页样式（构建时由公共皮肤复制）\n  demo/demo.js       示范脚本：五段流水线 + 现场训练/推理\n  README.txt         本文件\n\n演示口径\n--------\n所有井号、区块名、产量与工时均为教学示范口径，已脱敏；\n模型指标是合成数据上的现场计算结果，不代表任何一口真实井。"},{"name":"demo/demo.css","size":15946,"mime":"text/plain","enc":"text","data":"/* =========================================================\r\n   案例示范页 · 公共皮肤 Demo Base Skin\r\n   ---------------------------------------------------------\r\n   这份文件是「案例包 demo/demo.css」的统一母版：\r\n   tools/build-cases.mjs 会把它原样复制到每个案例包的\r\n   cases/<id>/demo/demo.css，保证所有示范页长得像一家人。\r\n\r\n   示范页运行在 sandbox iframe 里，与主站互不影响，\r\n   因此这里自带一套令牌，不依赖主站的 CSS。\r\n   ========================================================= */\r\n\r\n:root{\r\n  --ink:#1a2428; --ink-2:#4a585c; --ink-3:#6f7a7c; --ink-4:#99a3a4;\r\n  --paper:#f6f2e8; --paper-2:#efe9dd; --paper-3:#e5dcc9;\r\n  --card:#fffefa; --card-soft:#faf7f0;\r\n  --line:#e3dccd; --line-2:#d3c9b6; --line-3:#beb19a;\r\n  --jade:#245c5a; --jade-d:#123a3d; --jade-l:#e7eee9;\r\n  --clay:#a9742c; --clay-d:#83551f; --clay-l:#f4e8d4;\r\n  --ok:#3d7455; --ok-bg:#e8f0e7;\r\n  --warn:#9a6b1d; --warn-bg:#f4e8d4;\r\n  --bad:#a64b3c; --bad-bg:#f7e8e2;\r\n  --cv:#245c5a; --ts:#a9742c; --nlp:#5a6b78; --opt:#355c74; --kg:#6e6a3c;\r\n  --mono:'JetBrains Mono','SFMono-Regular','Cascadia Mono',Consolas,'Liberation Mono',monospace;\r\n  --sans:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI','PingFang SC','Microsoft YaHei UI','Microsoft YaHei',sans-serif;\r\n}\r\n\r\n*{box-sizing:border-box;margin:0;padding:0}\r\nbody{\r\n  font-family:var(--sans);font-size:13.5px;line-height:1.7;color:var(--ink);\r\n  background:var(--paper);padding:16px 18px 20px;-webkit-font-smoothing:antialiased;\r\n}\r\nb,strong{font-weight:650;color:var(--ink)}\r\n.mono{font-family:var(--mono);font-variant-numeric:tabular-nums}\r\n\r\n/* ---------- 头部 ---------- */\r\n.dhead{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:18px;align-items:start;margin-bottom:12px}\r\n.dhead h1{font-size:17px;letter-spacing:-.01em;line-height:1.3}\r\n.dhead .lead{font-size:12px;color:var(--ink-3);line-height:1.7;margin-top:5px;max-width:76ch}\r\n.dkick{\r\n  font-family:var(--mono);font-size:9px;letter-spacing:.16em;color:var(--jade-d);\r\n  display:inline-flex;align-items:center;gap:7px;margin-bottom:6px;text-transform:uppercase;\r\n}\r\n.dkick::before{content:'';width:16px;height:1.5px;background:currentColor;opacity:.5}\r\n.dhead-r{display:flex;gap:7px;flex-wrap:wrap;justify-content:flex-end;padding-top:2px}\r\n.dstat{\r\n  border:1px solid var(--line);background:var(--card);border-radius:7px;padding:5px 10px;min-width:74px;\r\n}\r\n.dstat .k{font-family:var(--mono);font-size:8px;letter-spacing:.1em;color:var(--ink-4);white-space:nowrap}\r\n.dstat .v{font-family:var(--mono);font-size:14px;color:var(--ink);line-height:1.35}\r\n.dstat .v small{font-size:8.5px;color:var(--ink-4);margin-left:2px;font-family:var(--sans)}\r\n.dstat.good .v{color:var(--ok)}.dstat.warn .v{color:var(--warn)}.dstat.bad .v{color:var(--bad)}\r\n\r\n/* ---------- 控制条 ---------- */\r\n.dctl{\r\n  display:flex;align-items:center;gap:18px;flex-wrap:wrap;\r\n  padding:10px 13px;border:1px solid var(--line);border-radius:9px;\r\n  background:var(--card-soft);margin-bottom:12px;\r\n}\r\n.dctl .grp{display:flex;align-items:center;gap:8px}\r\n.dctl .glbl{font-family:var(--mono);font-size:8.5px;letter-spacing:.12em;color:var(--ink-4);white-space:nowrap}\r\n.dctl .sp{flex:1}\r\n\r\n.ctl-s{display:flex;align-items:center;gap:8px}\r\n.ctl-s label{font-family:var(--mono);font-size:9px;letter-spacing:.06em;color:var(--ink-3);white-space:nowrap}\r\n.ctl-s output{font-family:var(--mono);font-size:11.5px;color:var(--jade-d);font-weight:600;min-width:38px;text-align:right}\r\ninput[type=range]{\r\n  -webkit-appearance:none;appearance:none;width:132px;height:3px;border-radius:2px;\r\n  background:var(--line-2);outline:none;cursor:pointer;\r\n}\r\ninput[type=range]::-webkit-slider-thumb{\r\n  -webkit-appearance:none;appearance:none;width:14px;height:14px;border-radius:50%;\r\n  background:var(--jade);border:2px solid #fff;box-shadow:0 0 0 1px var(--jade);\r\n}\r\ninput[type=range]::-moz-range-thumb{width:12px;height:12px;border-radius:50%;background:var(--jade);border:2px solid #fff}\r\n\r\n.seg{display:inline-flex;flex-wrap:wrap;border:1px solid var(--line-2);border-radius:5px;background:var(--card);padding:2px;gap:2px;max-width:100%}\r\n.seg button{\r\n  --mc:var(--jade);\r\n  font-family:var(--sans);font-size:11.5px;color:var(--ink-2);padding:4px 11px;border-radius:3px;white-space:nowrap;\r\n  transition:background .15s,color .15s;\r\n}\r\n.seg button:hover{color:var(--ink)}\r\n.seg button.on{background:var(--mc);color:#fff;font-weight:500}\r\n.seg button.on[data-c]{background:var(--mc);color:#fff}\r\n.seg button[data-c=\"cv\"]{--mc:var(--cv)}.seg button[data-c=\"ts\"]{--mc:var(--ts)}\r\n.seg button[data-c=\"nlp\"]{--mc:var(--nlp)}.seg button[data-c=\"opt\"]{--mc:var(--opt)}\r\n.seg button[data-c=\"kg\"]{--mc:var(--kg)}\r\n\r\n.dbtn{\r\n  display:inline-flex;align-items:center;gap:6px;font-size:11.5px;padding:5px 12px;\r\n  border:1px solid var(--line-2);border-radius:100px;background:var(--card);color:var(--ink-2);\r\n  transition:all .15s;cursor:pointer;white-space:nowrap;\r\n}\r\n.dbtn:hover{border-color:var(--line-3);color:var(--ink)}\r\n.dbtn.pri{background:var(--jade);border-color:var(--jade);color:#fff;font-weight:600}\r\n.dbtn.pri:hover{background:var(--jade-d);border-color:var(--jade-d)}\r\n.dbtn:disabled{opacity:.45;cursor:not-allowed;filter:grayscale(.4)}\r\n\r\n.tog{display:inline-flex;align-items:center;gap:7px;cursor:pointer;font-size:11.5px;color:var(--ink-2);user-select:none}\r\n.tog i{width:30px;height:16px;border-radius:9px;background:var(--line-2);position:relative;transition:background .16s;flex-shrink:0}\r\n.tog i::after{content:'';position:absolute;left:2px;top:2px;width:12px;height:12px;border-radius:50%;background:#fff;box-shadow:0 1px 2px rgba(0,0,0,.18);transition:transform .16s}\r\n.tog.on i{background:rgba(20,112,92,.45)}\r\n.tog.on i::after{transform:translateX(14px);background:var(--jade-d)}\r\n\r\n/* ---------- 布局 ---------- */\r\n.dgrid{display:grid;gap:12px}\r\n.dgrid.c2{grid-template-columns:minmax(0,1fr) minmax(0,340px)}\r\n.dgrid.c2b{grid-template-columns:minmax(0,340px) minmax(0,1fr)}\r\n.dgrid.c3{grid-template-columns:repeat(3,minmax(0,1fr))}\r\n.dcol{display:flex;flex-direction:column;gap:12px;min-width:0}\r\n.drow{display:flex;gap:12px;flex-wrap:wrap}\r\n\r\n/* ---------- 图框 ---------- */\r\n.dfig{border:1px solid var(--line);border-radius:9px;background:var(--card);padding:10px 11px 8px}\r\n.dfig-h{\r\n  display:flex;align-items:baseline;justify-content:space-between;gap:10px;\r\n  font-family:var(--mono);font-size:8.5px;letter-spacing:.1em;color:var(--ink-4);\r\n  margin-bottom:7px;text-transform:uppercase;\r\n}\r\n.dfig-h b{color:var(--ink-3);font-weight:500;letter-spacing:0;text-transform:none;font-family:var(--sans);font-size:11px}\r\n.dfig svg{display:block;width:100%;height:auto}\r\n.dfig-foot{\r\n  display:flex;gap:12px;flex-wrap:wrap;border-top:1px solid var(--line);\r\n  margin-top:8px;padding-top:7px;font-size:10.5px;color:var(--ink-4);\r\n}\r\n.dfig-foot span{display:flex;align-items:center;gap:5px}\r\n.dfig-foot i{width:13px;height:3px;border-radius:2px;display:block;flex-shrink:0}\r\n.dfig-foot i.dash{height:0;border-top:1.5px dashed var(--jade);background:none!important}\r\n\r\n/* ---------- 读数 / 指标 ---------- */\r\n.dread{display:grid;grid-template-columns:repeat(auto-fit,minmax(96px,1fr));gap:1px;background:var(--line);border:1px solid var(--line);border-radius:9px;overflow:hidden}\r\n.dread > div{background:var(--card);padding:8px 10px}\r\n.dread .k{font-family:var(--mono);font-size:8px;letter-spacing:.09em;color:var(--ink-4);white-space:nowrap}\r\n.dread .v{font-family:var(--mono);font-size:16px;line-height:1.3;margin-top:2px;color:var(--ink)}\r\n.dread .v small{font-size:8.5px;color:var(--ink-4);margin-left:2px;font-family:var(--sans)}\r\n.dread .v.ok{color:var(--ok)}.dread .v.warn{color:var(--warn)}.dread .v.bad{color:var(--bad)}\r\n\r\n.dnote{\r\n  font-size:11.5px;color:var(--ink-3);line-height:1.7;padding:9px 12px;\r\n  border-left:2.5px solid var(--clay);background:linear-gradient(90deg,rgba(192,118,43,.07),transparent 76%);\r\n  border-radius:0 4px 4px 0;\r\n}\r\n.dnote b{color:var(--ink)}\r\n.dnote.ok{border-left-color:var(--ok);background:linear-gradient(90deg,rgba(61,133,88,.07),transparent 76%)}\r\n.dnote.bad{border-left-color:var(--bad);background:linear-gradient(90deg,rgba(176,84,74,.07),transparent 76%)}\r\n\r\n/* ---------- 徽标 ---------- */\r\n.db{display:inline-flex;align-items:center;gap:5px;font-family:var(--mono);font-size:9.5px;letter-spacing:.05em;padding:2px 8px;border-radius:5px;border:1px solid;white-space:nowrap}\r\n.db.ok{color:var(--ok);border-color:rgba(61,133,88,.28);background:var(--ok-bg)}\r\n.db.warn{color:var(--warn);border-color:rgba(168,121,27,.28);background:var(--warn-bg)}\r\n.db.bad{color:var(--bad);border-color:rgba(176,84,74,.28);background:var(--bad-bg)}\r\n.db.plain{color:var(--ink-3);border-color:var(--line-2);background:var(--card-soft)}\r\n.db::before{content:'';width:4px;height:4px;border-radius:50%;background:currentColor}\r\n\r\n/* ---------- 列表 / 卡片 ---------- */\r\n.dcard{border:1px solid var(--line);border-radius:9px;background:var(--card);padding:10px 12px}\r\n.dcard + .dcard{margin-top:7px}\r\n.dcard h4{font-size:12.5px;display:flex;align-items:center;gap:8px;flex-wrap:wrap}\r\n.dcard p{font-size:11px;color:var(--ink-3);line-height:1.6;margin-top:4px}\r\n.dcard .top{display:flex;align-items:baseline;justify-content:space-between;gap:10px}\r\n.dcard .rank{font-family:var(--mono);font-size:9px;color:var(--ink-4);letter-spacing:.08em}\r\n\r\n.dtable{width:100%;border-collapse:collapse;font-size:11.5px}\r\n.dtable th{\r\n  font-family:var(--mono);font-size:8.5px;letter-spacing:.08em;color:var(--ink-4);font-weight:400;\r\n  text-align:left;padding:6px 10px 6px 0;border-bottom:1px solid var(--line-2);white-space:nowrap;\r\n}\r\n.dtable td{padding:7px 10px 7px 0;border-bottom:1px solid var(--line);color:var(--ink-2);vertical-align:top}\r\n.dtable tr:last-child td{border-bottom:0}\r\n.dtable td:first-child{color:var(--ink);white-space:nowrap}\r\n.dtable .num{font-family:var(--mono);text-align:right}\r\n\r\n/* 横向评分条 */\r\n.dbar{display:flex;align-items:center;gap:8px;font-size:11px;color:var(--ink-3)}\r\n.dbar .track{flex:1;height:6px;border-radius:3px;background:var(--paper-3);overflow:hidden;min-width:40px}\r\n.dbar .track i{display:block;height:100%;background:var(--jade);border-radius:3px;transition:width .25s}\r\n.dbar .track i.clay{background:var(--clay)}\r\n.dbar .track i.bad{background:var(--bad)}\r\n.dbar .track i.opt{background:var(--opt)}\r\n.dbar .val{font-family:var(--mono);font-size:10.5px;color:var(--ink-2);min-width:34px;text-align:right}\r\n\r\n/* 图例 */\r\n.dlg{display:flex;flex-wrap:wrap;gap:12px;font-size:10.5px;color:var(--ink-4)}\r\n.dlg span{display:flex;align-items:center;gap:5px}\r\n.dlg i{width:11px;height:3px;border-radius:2px;display:block;flex-shrink:0}\r\n.dlg i.sq{width:9px;height:9px;border-radius:2px}\r\n\r\n/* ---------- 焦点与触控 ---------- */\r\nbutton:focus-visible,input:focus-visible,.tog:focus-visible,[tabindex]:focus-visible{outline:2px solid var(--clay);outline-offset:2px}\r\n.tog{min-height:26px}\r\ninput[type=range]{height:16px}\r\nbutton{touch-action:manipulation}\r\n.dbtn.reset{margin-left:auto}\r\n\r\n/* ---------- 响应式 ---------- */\r\n@media (max-width:900px){\r\n  .dgrid.c2,.dgrid.c2b,.dgrid.c3{grid-template-columns:minmax(0,1fr)}\r\n  .dhead{grid-template-columns:minmax(0,1fr)}\r\n  .dhead-r{justify-content:flex-start}\r\n}\r\n\n/* =========================================================\n   AI 作业流示范（v4）\n   ---------------------------------------------------------\n   每个案例页都要能看见「现场输入 → 特征/知识化 → 模型推理 →\n   决策交付 → 闭环回写」这条链，而不是只摆一张结果图。\n   ========================================================= */\n.dflow{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));border:1px solid var(--line);border-radius:9px;background:var(--card);overflow:hidden;margin-bottom:12px}\n.dflow button{position:relative;border:0;border-right:1px solid var(--line);background:transparent;text-align:left;padding:8px 11px 9px;cursor:pointer;font-family:var(--sans);min-width:0;appearance:none}\n.dflow button:last-child{border-right:0}\n.dflow button .n{font-family:var(--mono);font-size:8px;letter-spacing:.13em;color:var(--ink-4);display:flex;align-items:center;gap:6px;text-transform:uppercase}\n.dflow button .n i{width:15px;height:15px;border-radius:50%;border:1px solid var(--line-2);display:inline-flex;align-items:center;justify-content:center;font-style:normal;font-size:8px;color:var(--ink-4);background:var(--card-soft);flex-shrink:0}\n.dflow button b{display:block;font-size:11.5px;font-weight:600;color:var(--ink-2);margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.dflow button span{display:block;font-size:9px;color:var(--ink-4);margin-top:1px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.dflow button:hover b{color:var(--ink)}\n.dflow button.on{background:linear-gradient(180deg,var(--jade-l),rgba(231,238,233,.3))}\n.dflow button.on b{color:var(--jade-d)}\n.dflow button.on .n i{border-color:var(--jade);background:var(--jade);color:#fff}\n.dflow button.done .n i{background:var(--ok);border-color:var(--ok);color:#fff}\n.dflow button.on::after{content:'';position:absolute;left:0;right:0;bottom:0;height:2px;background:var(--jade)}\n\n.dstage{display:none}\n.dstage.on{display:block}\n.dstage-lede{font-size:11.5px;color:var(--ink-3);line-height:1.7;margin:3px 0 9px}\n.dstage-lede b{color:var(--ink)}\n.dstage-tag{font-family:var(--mono);font-size:8px;letter-spacing:.12em;color:var(--ink-4);text-transform:uppercase}\n\n.dmodel{border:1px solid var(--line);border-radius:9px;background:var(--card);padding:9px 12px 8px}\n.dmodel-h{display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:11px;color:var(--ink-3);margin-bottom:4px}\n.dmodel-row{display:grid;grid-template-columns:78px minmax(0,1fr);gap:8px;padding:5px 0;border-bottom:1px dashed var(--line);font-size:10.5px;line-height:1.55}\n.dmodel-row:last-child{border-bottom:0}\n.dmodel-row .k{font-family:var(--mono);font-size:8px;letter-spacing:.07em;color:var(--ink-4);padding-top:2px}\n.dmodel-row .v{color:var(--ink-2)}\n\n.dtrace{border-left:2px solid var(--jade);background:var(--card-soft);border-radius:0 6px 6px 0;padding:7px 10px;font-family:var(--mono);font-size:9.5px;line-height:1.8;color:var(--ink-3);max-height:132px;overflow:auto}\n.dtrace div{display:flex;gap:7px}\n.dtrace .t{color:var(--ink-4);flex-shrink:0}\n.dtrace b{color:var(--jade-d);font-weight:600}\n.dtrace .ok{color:var(--ok)}\n.dtrace .warn{color:var(--warn)}\n.dtrace .bad{color:var(--bad)}\n\n.dval{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1px;background:var(--line);border:1px solid var(--line);border-radius:8px;overflow:hidden}\n.dval > div{background:var(--card);padding:8px 10px}\n.dval .k{font-family:var(--mono);font-size:8px;letter-spacing:.08em;color:var(--ink-4);white-space:nowrap}\n.dval .v{font-family:var(--mono);font-size:15px;line-height:1.35;margin-top:2px;color:var(--ink)}\n.dval .v small{font-family:var(--sans);font-size:8.5px;color:var(--ink-4);margin-left:2px}\n.dval .v.ok{color:var(--ok)}.dval .v.warn{color:var(--warn)}.dval .v.bad{color:var(--bad)}\n.dval .s{font-size:9.5px;color:var(--ink-4);line-height:1.5;margin-top:1px}\n\n.dcm{display:grid;gap:2px 4px;font-family:var(--mono);font-size:9px;align-items:center}\n.dcm .lb{text-align:right;color:var(--ink-4);font-size:8px;white-space:nowrap;overflow:hidden}\n.dcm i{display:block;height:15px;border-radius:2px}\n\n.dcurve{display:block;width:100%;height:auto}\n\n.dfeed{display:flex;gap:7px;flex-wrap:wrap;align-items:center}\n.dfeed .dbtn{padding:4px 9px;font-size:10.5px}\n.dfeed-note{font-size:10px;color:var(--ink-4);line-height:1.6}\n\n@media (max-width:900px){\n  .dflow{grid-template-columns:repeat(2,minmax(0,1fr))}\n  .dflow button{border-bottom:1px solid var(--line)}\n  .dval{grid-template-columns:minmax(0,1fr)}\n}\n"},{"name":"demo/demo.js","size":49936,"mime":"text/plain","enc":"text","data":"/* =========================================================\r\n   修井周期预测 · 可运行示范（v4 · AI 作业流）\r\n   ---------------------------------------------------------\r\n   这条流水线回答的不是「这口井大概几天」，而是：\r\n     历史工单 → 能不能用 → 模型看到什么 → 区间多准 → 怎么承诺\r\n   ① 工单采集与质控：1450 井次 × 7 道工序，剔除异常/缺段/截断；\r\n   ② 特征：井深、故障 one-hot、复杂度、工序数、打捞/套管/磨铣/压井；\r\n   ③ 模型：7 道工序 × P10/P50/P90 = 21 组线性分位数回归，\r\n      标准化 + pinball loss + 梯度下降，本页现场训练，留出 20% 验证；\r\n   ④ 合成：工序分位 → 对数正态 + 共同因子相关 → 2000 次抽样相加；\r\n   ⑤ 决策：计划工期滑杆 → 按期概率 / P80 承诺 / 人工回写。\r\n   统计口径：工单与指标均为合成示范，价值数字（MAPE、兑现率、\r\n   计划编制时间）是 1450 井次的示范口径，不是本页仿真读数。\r\n   ========================================================= */\r\n(function () {\r\n  'use strict';\r\n\r\n  /* ---------------- 业务常量 ---------------- */\r\n  var FAULTS = [\r\n    { key: 'fish', name: '落物打捞', f: 1.00, millP: 0.55 },\r\n    { key: 'casing', name: '套管整形', f: 1.25, millP: 0.88 },\r\n    { key: 'water', name: '找堵水', f: 0.85, millP: 0.20 },\r\n    { key: 'sand', name: '冲砂防砂', f: 0.90, millP: 0.30 },\r\n    { key: 'part', name: '管柱断脱', f: 1.35, millP: 0.50 }\r\n  ];\r\n\r\n  /* 工序：a=固定耗时(天)，b=每千米井深增加(天/km)，s=对数正态形状参数，\r\n     w=复杂度对这道工序的影响权重（打捞/磨铣为 1.0） */\r\n  var PROCS = [\r\n    { name: '起原井管柱', a: 0.35, b: 0.55, s: 0.20, w: 0.45 },\r\n    { name: '洗井 / 循环', a: 0.20, b: 0.12, s: 0.28, w: 0.12 },\r\n    { name: '打捞 / 磨铣', a: 1.10, b: 0.90, s: 0.55, w: 1.00 },\r\n    { name: '通井', a: 0.35, b: 0.30, s: 0.30, w: 0.35 },\r\n    { name: '下泵 / 下管柱', a: 0.45, b: 0.45, s: 0.22, w: 0.45 },\r\n    { name: '试压', a: 0.20, b: 0.03, s: 0.35, w: 0.12 },\r\n    { name: '交井 / 收尾', a: 0.25, b: 0.02, s: 0.40, w: 0.12 }\r\n  ];\r\n\r\n  var QS = [0.1, 0.5, 0.9];\r\n  var D = 9;\r\n  var EP = 200, LR = 0.12, L2 = 0.002;\r\n  var MC_N = 2000, LOAD = 0.6;\r\n  var ZP = 1.2815515655;\r\n  var SEED_TICKET = 20261031, SEED_DEFECT = 777, SEED_SPLIT = 4242, SEED_MC = 101581;\r\n  var RAW_N = 1450, N_BAD = 47, N_MISS = 51, N_TRUNC = 30;\r\n\r\n  var DEFAULTS = { fault: 'fish', depth: 2400, mill: true, kill: true, plan: 10 };\r\n  var state = {\r\n    fault: DEFAULTS.fault, depth: DEFAULTS.depth, mill: DEFAULTS.mill,\r\n    kill: DEFAULTS.kill, plan: DEFAULTS.plan\r\n  };\r\n  var fb = { adopt: 0, adjust: 0 };\r\n  var LAST = null;\r\n\r\n  /* ---------------- 随机数 ---------------- */\r\n  function mulberry32(a) {\r\n    return function () {\r\n      a |= 0; a = a + 0x6D2B79F5 | 0;\r\n      var t = Math.imul(a ^ a >>> 15, 1 | a);\r\n      t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;\r\n      return ((t ^ t >>> 14) >>> 0) / 4294967296;\r\n    };\r\n  }\r\n  function makeGauss(rnd) {\r\n    var spare = null;\r\n    return function () {\r\n      if (spare != null) { var v0 = spare; spare = null; return v0; }\r\n      var u = 0, v = 0;\r\n      while (u === 0) u = rnd();\r\n      while (v === 0) v = rnd();\r\n      var m = Math.sqrt(-2 * Math.log(u));\r\n      spare = m * Math.sin(2 * Math.PI * v);\r\n      return m * Math.cos(2 * Math.PI * v);\r\n    };\r\n  }\r\n  function faultOf(k) {\r\n    for (var i = 0; i < FAULTS.length; i++) if (FAULTS[i].key === k) return FAULTS[i];\r\n    return FAULTS[0];\r\n  }\r\n\r\n  /* =========================================================\r\n     01 工单采集与质控\r\n     - 1450 井次，按 7 道标准工序生成耗时；\r\n     - 47 条异常（耗时为负/顺序错）、51 条缺工序、30 条截断；\r\n     - 质控后 1322 条进入训练/验证。\r\n     ========================================================= */\r\n  function buildData() {\r\n    var rnd = mulberry32(SEED_TICKET), gauss = makeGauss(rnd);\r\n    var tickets = [], i, p;\r\n    for (i = 0; i < RAW_N; i++) {\r\n      var fault = FAULTS[Math.floor(rnd() * FAULTS.length)];\r\n      var depth = 1200 + Math.floor(rnd() * 49) * 50;\r\n      var mill = rnd() < fault.millP;\r\n      var kill = rnd() < 0.62;\r\n      var comp = fault.f * (mill ? 1.18 : 1) * (kill ? 1.06 : 1);\r\n      var km = depth / 1000;\r\n      var u = gauss();\r\n      var durs = [];\r\n      for (p = 0; p < PROCS.length; p++) {\r\n        var pr = PROCS[p];\r\n        var m = (pr.a + pr.b * km) * (1 + (comp - 1) * pr.w);\r\n        var z = 0.6 * u + 0.8 * gauss();\r\n        durs.push(m * Math.exp(pr.s * z));\r\n      }\r\n      tickets.push({\r\n        depth: depth, fault: fault, mill: mill, kill: kill,\r\n        compOp: (mill ? 0.6 : 0) + (kill ? 0.4 : 0),\r\n        nproc: 7 + (mill ? 1 : 0) + (kill ? 1 : 0),\r\n        durs: durs\r\n      });\r\n    }\r\n\r\n    /* 质控缺陷：固定条数、固定随机顺序，保证每次打开页面一致 */\r\n    var order = [];\r\n    for (i = 0; i < tickets.length; i++) order.push(i);\r\n    var sr = mulberry32(SEED_DEFECT);\r\n    for (i = order.length - 1; i > 0; i--) {\r\n      var j = Math.floor(sr() * (i + 1));\r\n      var tmp = order[i]; order[i] = order[j]; order[j] = tmp;\r\n    }\r\n    var defect = {};\r\n    for (i = 0; i < N_BAD; i++) defect[order[i]] = 'bad';\r\n    for (i = N_BAD; i < N_BAD + N_MISS; i++) defect[order[i]] = 'miss';\r\n    for (i = N_BAD + N_MISS; i < N_BAD + N_MISS + N_TRUNC; i++) defect[order[i]] = 'trunc';\r\n\r\n    var qc = { raw: RAW_N, bad: 0, miss: 0, trunc: 0, ok: 0 };\r\n    var usable = [];\r\n    for (i = 0; i < tickets.length; i++) {\r\n      var t = tickets[i], d = defect[i];\r\n      if (d === 'bad') {\r\n        qc.bad++; t.defect = 'bad';\r\n        t.durs[2] = -0.3;                    /* 负耗时：不可能进模型 */\r\n        continue;\r\n      }\r\n      if (d === 'miss') {\r\n        qc.miss++; t.defect = 'miss';\r\n        t.durs[2] = NaN;                     /* 7 道缺 1 */\r\n        continue;\r\n      }\r\n      if (d === 'trunc') {\r\n        qc.trunc++; t.defect = 'trunc';\r\n        var sum = 0;\r\n        for (p = 0; p < t.durs.length; p++) sum += t.durs[p];\r\n        var k = 2.6 / sum;\r\n        for (p = 0; p < t.durs.length; p++) t.durs[p] *= k;  /* 系统在 2.6 天截断 */\r\n        continue;\r\n      }\r\n      qc.ok++; usable.push(t);\r\n    }\r\n    return { tickets: tickets, usable: usable, qc: qc };\r\n  }\r\n\r\n  /* =========================================================\r\n     02 特征：模型只吃这 9 个数\r\n     ========================================================= */\r\n  function feats(t) {\r\n    return [\r\n      t.depth / 1000,\r\n      t.fault.key === 'fish' ? 1 : 0,\r\n      t.fault.key === 'casing' ? 1 : 0,\r\n      t.fault.key === 'water' ? 1 : 0,\r\n      t.fault.key === 'sand' ? 1 : 0,\r\n      t.compOp,\r\n      t.nproc,\r\n      t.mill ? 1 : 0,\r\n      t.kill ? 1 : 0\r\n    ];\r\n  }\r\n\r\n  /* =========================================================\r\n     03 分位数回归：21 组线性模型，pinball loss 现场训练\r\n     ========================================================= */\r\n  function dot(m, x) {\r\n    var s = m.b;\r\n    for (var j = 0; j < D; j++) s += m.w[j] * x[j];\r\n    return s;\r\n  }\r\n\r\n  function predictFromX(x, models) {\r\n    var out = [];\r\n    for (var p = 0; p < 7; p++) {\r\n      var a = Math.exp(dot(models[p * 3], x));\r\n      var b = Math.exp(dot(models[p * 3 + 1], x));\r\n      var c = Math.exp(dot(models[p * 3 + 2], x));\r\n      var arr = [a, b, c].sort(function (u, v) { return u - v; });\r\n      out.push({ p10: arr[0], p50: arr[1], p90: arr[2] });\r\n    }\r\n    return out;\r\n  }\r\n\r\n  function valLoss(X, set, models) {\r\n    var total = 0;\r\n    for (var n = 0; n < X.length; n++) {\r\n      var x = X[n];\r\n      for (var mi = 0; mi < models.length; mi++) {\r\n        var m = models[mi];\r\n        var e = Math.log(set[n].durs[m.p]) - dot(m, x);\r\n        total += e > 0 ? m.tau * e : (m.tau - 1) * e;\r\n      }\r\n    }\r\n    return total / X.length / models.length;\r\n  }\r\n\r\n  function trainModel(data) {\r\n    var usable = data.usable, i, j, p, qi, mi, n, ep;\r\n    var idx = [];\r\n    for (i = 0; i < usable.length; i++) idx.push(i);\r\n    var sr = mulberry32(SEED_SPLIT);\r\n    for (i = idx.length - 1; i > 0; i--) {\r\n      var jj = Math.floor(sr() * (i + 1));\r\n      var tmp = idx[i]; idx[i] = idx[jj]; idx[jj] = tmp;\r\n    }\r\n    var nVal = Math.round(usable.length * 0.2);\r\n    var nTrain = usable.length - nVal;\r\n    var trainSet = [], valSet = [];\r\n    for (i = 0; i < nTrain; i++) trainSet.push(usable[idx[i]]);\r\n    for (i = nTrain; i < usable.length; i++) valSet.push(usable[idx[i]]);\r\n\r\n    /* 特征标准化（只用训练集统计量） */\r\n    var mu = new Array(D), sd = new Array(D);\r\n    for (j = 0; j < D; j++) { mu[j] = 0; sd[j] = 0; }\r\n    for (i = 0; i < trainSet.length; i++) {\r\n      var xr = feats(trainSet[i]);\r\n      for (j = 0; j < D; j++) mu[j] += xr[j];\r\n    }\r\n    for (j = 0; j < D; j++) mu[j] /= trainSet.length;\r\n    for (i = 0; i < trainSet.length; i++) {\r\n      xr = feats(trainSet[i]);\r\n      for (j = 0; j < D; j++) sd[j] += Math.pow(xr[j] - mu[j], 2);\r\n    }\r\n    for (j = 0; j < D; j++) sd[j] = Math.sqrt(sd[j] / trainSet.length) || 1;\r\n    function sx(t) {\r\n      var raw = feats(t), z = new Array(D);\r\n      for (var k = 0; k < D; k++) z[k] = (raw[k] - mu[k]) / sd[k];\r\n      return z;\r\n    }\r\n    var Xtr = [], Xval = [];\r\n    for (i = 0; i < trainSet.length; i++) Xtr.push(sx(trainSet[i]));\r\n    for (i = 0; i < valSet.length; i++) Xval.push(sx(valSet[i]));\r\n\r\n    /* 21 组模型：7 道工序 × 3 个分位 */\r\n    var models = [];\r\n    for (p = 0; p < 7; p++) {\r\n      for (qi = 0; qi < 3; qi++) {\r\n        models.push({\r\n          p: p, tau: QS[qi],\r\n          w: new Array(D).fill(0), vw: new Array(D).fill(0),\r\n          b: 0, vb: 0, gw: new Array(D).fill(0), gb: 0, loss: 0\r\n        });\r\n      }\r\n    }\r\n\r\n    var hist = [], vhist = [];\r\n    for (ep = 0; ep < EP; ep++) {\r\n      for (mi = 0; mi < models.length; mi++) {\r\n        var mm = models[mi];\r\n        mm.gw.fill(0); mm.gb = 0; mm.loss = 0;\r\n      }\r\n      for (n = 0; n < Xtr.length; n++) {\r\n        var x = Xtr[n];\r\n        for (mi = 0; mi < models.length; mi++) {\r\n          mm = models[mi];\r\n          var y = Math.log(trainSet[n].durs[mm.p]);\r\n          var pred = mm.b;\r\n          for (j = 0; j < D; j++) pred += mm.w[j] * x[j];\r\n          var e = y - pred;\r\n          /* pinball loss 的次梯度：低估时 -tau，高估时 +(1-tau) */\r\n          var g = e > 0 ? -mm.tau : (1 - mm.tau);\r\n          mm.gb += g;\r\n          for (j = 0; j < D; j++) mm.gw[j] += g * x[j];\r\n          mm.loss += e > 0 ? mm.tau * e : (mm.tau - 1) * e;\r\n        }\r\n      }\r\n      for (mi = 0; mi < models.length; mi++) {\r\n        mm = models[mi];\r\n        mm.vb = 0.9 * mm.vb - LR * mm.gb / Xtr.length;\r\n        mm.b += mm.vb;\r\n        for (j = 0; j < D; j++) {\r\n          mm.vw[j] = 0.9 * mm.vw[j] - LR * (mm.gw[j] / Xtr.length + L2 * mm.w[j]);\r\n          mm.w[j] += mm.vw[j];\r\n        }\r\n      }\r\n      if (ep % 4 === 0 || ep === EP - 1) {\r\n        var tl = 0;\r\n        for (mi = 0; mi < models.length; mi++) tl += models[mi].loss;\r\n        hist.push(tl / Xtr.length / models.length);\r\n        vhist.push(valLoss(Xval, valSet, models));\r\n      }\r\n    }\r\n\r\n    /* 验证：覆盖率、P50 误差、校准桶、分位交叉 */\r\n    var cover = 0, tot = 0, c10 = 0, c90 = 0, cross = 0;\r\n    var absErr = [], cal = [];\r\n    for (n = 0; n < Xval.length; n++) {\r\n      var xv = Xval[n], tv = valSet[n];\r\n      var pr = predictFromX(xv, models);\r\n      for (p = 0; p < 7; p++) {\r\n        var raw10 = Math.exp(dot(models[p * 3], xv));\r\n        var raw50 = Math.exp(dot(models[p * 3 + 1], xv));\r\n        var raw90 = Math.exp(dot(models[p * 3 + 2], xv));\r\n        if (!(raw10 <= raw50 && raw50 <= raw90)) cross++;\r\n        var a = pr[p].p10, b50 = pr[p].p50, c = pr[p].p90;\r\n        var act = tv.durs[p];\r\n        tot++;\r\n        if (act >= a && act <= c) cover++;\r\n        if (act <= a) c10++;\r\n        if (act <= c) c90++;\r\n        absErr.push(Math.abs(b50 - act));\r\n        cal.push({ pred: b50, act: act });\r\n      }\r\n    }\r\n    absErr.sort(function (u, v) { return u - v; });\r\n    var medAE = absErr[Math.floor(absErr.length / 2)];\r\n\r\n    cal.sort(function (u, v) { return u.pred - v.pred; });\r\n    var calib = [];\r\n    for (var bi = 0; bi < 5; bi++) {\r\n      var seg = cal.slice(Math.floor(bi * cal.length / 5), Math.floor((bi + 1) * cal.length / 5));\r\n      var ps = [], as = [];\r\n      for (i = 0; i < seg.length; i++) { ps.push(seg[i].pred); as.push(seg[i].act); }\r\n      ps.sort(function (u, v) { return u - v; });\r\n      as.sort(function (u, v) { return u - v; });\r\n      calib.push({\r\n        pred: ps[Math.floor(ps.length / 2)],\r\n        act: as[Math.floor(as.length / 2)]\r\n      });\r\n    }\r\n\r\n    /* 总工期 P50 误差：每口验证井抽 120 次，与真实总工期比 */\r\n    var totalAE = [];\r\n    for (n = 0; n < Xval.length; n++) {\r\n      var pt = predictFromX(Xval[n], models);\r\n      var tt = simulateTotals(pt, 120, false).slice().sort(function (u, v) { return u - v; });\r\n      var medT = q(tt, 0.5);\r\n      var actT = 0;\r\n      for (p = 0; p < 7; p++) actT += valSet[n].durs[p];\r\n      totalAE.push(Math.abs(medT - actT));\r\n    }\r\n    totalAE.sort(function (u, v) { return u - v; });\r\n\r\n    return {\r\n      mu: mu, sd: sd, models: models, hist: hist, vhist: vhist,\r\n      nTrain: nTrain, nVal: nVal,\r\n      coverage: cover / tot, cover10: c10 / tot, cover90: c90 / tot,\r\n      cross: cross, medAE: medAE,\r\n      totalMedAE: totalAE[Math.floor(totalAE.length / 2)],\r\n      calib: calib\r\n    };\r\n  }\r\n\r\n  /* =========================================================\r\n     04 蒙特卡洛：预生成相关正态，固定随机流（common random numbers）\r\n     ========================================================= */\r\n  function buildMC() {\r\n    var Z = [], Z0 = [], i, p;\r\n    var r1 = mulberry32(SEED_MC), g1 = makeGauss(r1);\r\n    var r0 = mulberry32(SEED_MC + 1), g0 = makeGauss(r0);\r\n    for (i = 0; i < MC_N; i++) {\r\n      var z0 = g1(), row = [];\r\n      for (p = 0; p < 7; p++) row.push(LOAD * z0 + Math.sqrt(1 - LOAD * LOAD) * g1());\r\n      Z.push(row);\r\n      var row0 = [];\r\n      for (p = 0; p < 7; p++) row0.push(g0());\r\n      Z0.push(row0);\r\n    }\r\n    return { Z: Z, Z0: Z0 };\r\n  }\r\n\r\n  function sigmaOf(d) {\r\n    var s = Math.log(d.p90 / d.p10) / (2 * ZP);\r\n    return (!isFinite(s) || s <= 0) ? 0.2 : s;\r\n  }\r\n\r\n  function simulateTotals(preds, n, indep) {\r\n    var Z = indep ? MC.Z0 : MC.Z;\r\n    var out = new Array(n);\r\n    for (var i = 0; i < n; i++) {\r\n      var sum = 0;\r\n      for (var p = 0; p < 7; p++) {\r\n        sum += preds[p].p50 * Math.exp(sigmaOf(preds[p]) * Z[i][p]);\r\n      }\r\n      out[i] = sum;\r\n    }\r\n    return out;\r\n  }\r\n\r\n  function simulate(preds, n) {\r\n    var totals = new Array(n), per = [], p, i;\r\n    for (p = 0; p < 7; p++) per.push(new Array(n));\r\n    for (i = 0; i < n; i++) {\r\n      var sum = 0;\r\n      for (p = 0; p < 7; p++) {\r\n        var v = preds[p].p50 * Math.exp(sigmaOf(preds[p]) * MC.Z[i][p]);\r\n        per[p][i] = v;\r\n        sum += v;\r\n      }\r\n      totals[i] = sum;\r\n    }\r\n    var cum = [], run = new Array(n);\r\n    for (i = 0; i < n; i++) run[i] = 0;\r\n    for (p = 0; p < 7; p++) {\r\n      for (i = 0; i < n; i++) run[i] += per[p][i];\r\n      cum.push(run.slice());\r\n    }\r\n    return { totals: totals, per: per, cum: cum };\r\n  }\r\n\r\n  /* ---------------- 统计小工具 ---------------- */\r\n  function q(sorted, p) {\r\n    var i = Math.min(sorted.length - 1, Math.max(0, Math.round(p * (sorted.length - 1))));\r\n    return sorted[i];\r\n  }\r\n  function meanOf(a) {\r\n    var s = 0;\r\n    for (var i = 0; i < a.length; i++) s += a[i];\r\n    return s / a.length;\r\n  }\r\n  function statsOf(totals, plan) {\r\n    var sorted = totals.slice().sort(function (a, b) { return a - b; });\r\n    var n = sorted.length, i, ok = 0;\r\n    for (i = 0; i < n; i++) { if (sorted[i] <= plan) ok++; else break; }\r\n    return {\r\n      sorted: sorted,\r\n      p10: q(sorted, 0.1), p50: q(sorted, 0.5), p70: q(sorted, 0.7),\r\n      p80: q(sorted, 0.8), p90: q(sorted, 0.9),\r\n      mean: meanOf(totals), prob: ok / n\r\n    };\r\n  }\r\n  function inCdf(sorted, v) {\r\n    if (v < sorted[0]) return 0;\r\n    if (v >= sorted[sorted.length - 1]) return 1;\r\n    var lo = 0, hi = sorted.length - 1;\r\n    while (lo < hi) {\r\n      var mid = (lo + hi) >> 1;\r\n      if (sorted[mid] <= v) lo = mid + 1; else hi = mid;\r\n    }\r\n    return lo / sorted.length;\r\n  }\r\n  function sharesOf(res) {\r\n    var rawT = res.totals, n = rawT.length, meanT = meanOf(rawT);\r\n    var varT = 0, i, p;\r\n    for (i = 0; i < n; i++) varT += Math.pow(rawT[i] - meanT, 2);\r\n    varT /= n;\r\n    var shares = [];\r\n    for (p = 0; p < 7; p++) {\r\n      var arr = res.per[p], ma = meanOf(arr), cov = 0;\r\n      for (i = 0; i < n; i++) cov += (arr[i] - ma) * (rawT[i] - meanT);\r\n      shares.push(cov / n / varT);\r\n    }\r\n    return shares;\r\n  }\r\n  function corrOf(a, b) {\r\n    var n = a.length, ma = 0, mb = 0, i;\r\n    for (i = 0; i < n; i++) { ma += a[i]; mb += b[i]; }\r\n    ma /= n; mb /= n;\r\n    var ca = 0, va = 0, vb = 0;\r\n    for (i = 0; i < n; i++) {\r\n      var da = a[i] - ma, db = b[i] - mb;\r\n      ca += da * db; va += da * da; vb += db * db;\r\n    }\r\n    return ca / Math.sqrt(va * vb);\r\n  }\r\n\r\n  /* ---------------- 初始化数据与模型 ---------------- */\r\n  var DATA = buildData();\r\n  var MC = buildMC();\r\n  var MODEL = trainModel(DATA);\r\n\r\n  /* =========================================================\r\n     绘图\r\n     ========================================================= */\r\n  var el = function (id) { return document.getElementById(id); };\r\n  var C = { jade: '#1d4e50', jadeL: '#c8dbd2', clay: '#a9742c', clayL: '#f0e0c8', bad: '#a64b3c', ink3: '#6f7a7c', ink4: '#99a3a4', line: '#efece1' };\r\n\r\n  function drawGantt(res, stats, keyIdx) {\r\n    var W = 680, H = 210, L = 92, R = 150, T = 22, B = 30;\r\n    var rowH = (H - T - B) / PROCS.length;\r\n    var tmax = Math.ceil(stats.p90 * 1.05 / 2) * 2;\r\n    if (tmax < stats.p90 * 1.02) tmax += 2;\r\n    function x(t) { return L + t / tmax * (W - L - R); }\r\n    var s = '', i, t;\r\n    for (t = 0; t <= tmax + 1e-9; t += 2) {\r\n      s += '<line x1=\"' + x(t).toFixed(1) + '\" y1=\"' + T + '\" x2=\"' + x(t).toFixed(1) + '\" y2=\"' + (H - B) + '\" stroke=\"' + C.line + '\"/>' +\r\n        '<text x=\"' + x(t).toFixed(1) + '\" y=\"' + (T - 8) + '\" font-size=\"9\" fill=\"' + C.ink4 + '\" text-anchor=\"middle\" font-family=\"monospace\">' + t + '<\/text>';\r\n    }\r\n    var prev50 = 0;\r\n    for (i = 0; i < PROCS.length; i++) {\r\n      var arr = res.cum[i].slice().sort(function (a, b) { return a - b; });\r\n      var c10 = q(arr, 0.1), c50 = q(arr, 0.5), c90 = q(arr, 0.9);\r\n      var y = T + i * rowH + rowH / 2;\r\n      var isKey = i === keyIdx;\r\n      s += '<text x=\"' + (L - 8) + '\" y=\"' + (y + 3.5) + '\" font-size=\"10\" text-anchor=\"end\" fill=\"' + (isKey ? C.clay : '#4a585c') + '\">' + PROCS[i].name + '<\/text>';\r\n      s += '<rect x=\"' + x(c10).toFixed(1) + '\" y=\"' + (y - 8) + '\" width=\"' + Math.max(1.5, x(c90) - x(c10)).toFixed(1) + '\" height=\"16\" rx=\"4\" fill=\"' + (isKey ? C.clayL : C.jadeL) + '\"/>';\r\n      s += '<rect x=\"' + x(prev50).toFixed(1) + '\" y=\"' + (y - 5) + '\" width=\"' + Math.max(1.5, x(c50) - x(prev50)).toFixed(1) + '\" height=\"10\" rx=\"3\" fill=\"' + (isKey ? C.clay : C.jade) + '\"/>';\r\n      s += '<text x=\"' + (W - R + 8) + '\" y=\"' + (y + 3.2) + '\" font-size=\"8.5\" font-family=\"monospace\" fill=\"' + C.ink3 + '\">完成 ' + c10.toFixed(1) + '—' + c90.toFixed(1) + ' 天<\/text>';\r\n      prev50 = c50;\r\n    }\r\n    var xp50 = x(stats.p50), xp90 = x(stats.p90);\r\n    s += '<line x1=\"' + xp50.toFixed(1) + '\" y1=\"' + (T - 2) + '\" x2=\"' + xp50.toFixed(1) + '\" y2=\"' + (H - B + 4) + '\" stroke=\"' + C.jade + '\" stroke-width=\"1.4\"/>';\r\n    s += '<line x1=\"' + xp90.toFixed(1) + '\" y1=\"' + (T - 2) + '\" x2=\"' + xp90.toFixed(1) + '\" y2=\"' + (H - B + 4) + '\" stroke=\"' + C.clay + '\" stroke-width=\"1.4\" stroke-dasharray=\"4 3\"/>';\r\n    var l50 = '总 P50 ' + stats.p50.toFixed(1) + ' 天', l90 = '总 P90 ' + stats.p90.toFixed(1) + ' 天';\r\n    if (Math.abs(xp90 - xp50) < 80) {\r\n      s += '<text x=\"' + (xp50 - 4).toFixed(1) + '\" y=\"' + (H - 9) + '\" font-size=\"9\" font-family=\"monospace\" fill=\"' + C.jade + '\" text-anchor=\"end\">' + l50 + '<\/text>';\r\n      s += '<text x=\"' + (xp90 + 4).toFixed(1) + '\" y=\"' + (H - 9) + '\" font-size=\"9\" font-family=\"monospace\" fill=\"' + C.clay + '\" text-anchor=\"start\">' + l90 + '<\/text>';\r\n    } else {\r\n      s += '<text x=\"' + xp50.toFixed(1) + '\" y=\"' + (H - 9) + '\" font-size=\"9\" font-family=\"monospace\" fill=\"' + C.jade + '\" text-anchor=\"middle\">' + l50 + '<\/text>';\r\n      s += '<text x=\"' + xp90.toFixed(1) + '\" y=\"' + (H - 9) + '\" font-size=\"9\" font-family=\"monospace\" fill=\"' + C.clay + '\" text-anchor=\"middle\">' + l90 + '<\/text>';\r\n    }\r\n    el('gantt').innerHTML = s;\r\n  }\r\n\r\n  function niceStep(v) {\r\n    var cand = [1, 2, 5, 10, 20, 25, 50, 100, 200, 500, 1000];\r\n    for (var i = 0; i < cand.length; i++) if (v / cand[i] <= 5.5) return cand[i];\r\n    return 2000;\r\n  }\r\n\r\n  function drawHist(sorted, stats) {\r\n    var W = 680, H = 165, L = 46, R = 16, T = 14, B = 34;\r\n    var lo = Math.floor(sorted[0] * 2) / 2, hi = Math.ceil(sorted[sorted.length - 1] * 2) / 2;\r\n    var bins = 30, bw = (hi - lo) / bins, counts = new Array(bins).fill(0);\r\n    var i, t;\r\n    for (i = 0; i < sorted.length; i++) {\r\n      var b = Math.min(bins - 1, Math.floor((sorted[i] - lo) / bw));\r\n      counts[b]++;\r\n    }\r\n    var cmax = Math.max.apply(null, counts);\r\n    var ystep = niceStep(cmax);\r\n    var ytop = Math.ceil(cmax / ystep) * ystep;\r\n    function x(v) { return L + (v - lo) / (hi - lo) * (W - L - R); }\r\n    function yb(c) { return H - B - c / ytop * (H - T - B); }\r\n    var s = '';\r\n    s += '<text x=\"6\" y=\"11\" font-size=\"8.5\" fill=\"' + C.ink4 + '\" font-family=\"monospace\">频数<\/text>';\r\n    for (var c = 0; c <= ytop + 1e-9; c += ystep) {\r\n      var yy = yb(c);\r\n      s += '<line x1=\"' + L + '\" y1=\"' + yy.toFixed(1) + '\" x2=\"' + (W - R) + '\" y2=\"' + yy.toFixed(1) + '\" stroke=\"' + C.line + '\"/>';\r\n      s += '<text x=\"' + (L - 6) + '\" y=\"' + (yy + 3).toFixed(1) + '\" font-size=\"8.5\" fill=\"' + C.ink4 + '\" text-anchor=\"end\" font-family=\"monospace\">' + c + '<\/text>';\r\n    }\r\n    s += '<line x1=\"' + L + '\" y1=\"' + T + '\" x2=\"' + L + '\" y2=\"' + (H - B) + '\" stroke=\"#d3c9b6\"/>';\r\n    for (i = 0; i < bins; i++) {\r\n      var v0 = lo + i * bw, v1 = v0 + bw;\r\n      var col;\r\n      if (v1 <= state.plan) col = '#c8dbd2';\r\n      else if (v0 >= state.plan) col = 'rgba(176,84,74,.55)';\r\n      else col = '#e6d3ae';\r\n      s += '<rect x=\"' + x(v0).toFixed(1) + '\" y=\"' + yb(counts[i]).toFixed(1) + '\" width=\"' + Math.max(1, x(v1) - x(v0) - 1).toFixed(1) + '\" height=\"' + (H - B - yb(counts[i])).toFixed(1) + '\" fill=\"' + col + '\"/>';\r\n    }\r\n    s += '<line x1=\"' + L + '\" y1=\"' + (H - B) + '\" x2=\"' + (W - R) + '\" y2=\"' + (H - B) + '\" stroke=\"#d3c9b6\"/>';\r\n    var span = hi - lo;\r\n    var stepX = span > 20 ? 5 : span > 10 ? 2 : 1;\r\n    for (t = Math.ceil(lo); t <= hi; t += stepX) {\r\n      s += '<text x=\"' + x(t).toFixed(1) + '\" y=\"' + (H - B + 13) + '\" font-size=\"9\" fill=\"' + C.ink4 + '\" text-anchor=\"middle\" font-family=\"monospace\">' + t + '<\/text>';\r\n    }\r\n    s += '<text x=\"' + ((L + W - R) / 2).toFixed(1) + '\" y=\"' + (H - 7) + '\" font-size=\"9\" fill=\"' + C.ink4 + '\" text-anchor=\"middle\">总工期 / 天<\/text>';\r\n\r\n    function vline(v, col, label, dash, ly, anchor, xo) {\r\n      var xx = xo != null ? xo : x(v);\r\n      return '<line x1=\"' + xx.toFixed(1) + '\" y1=\"' + T + '\" x2=\"' + xx.toFixed(1) + '\" y2=\"' + (H - B) + '\" stroke=\"' + col + '\" stroke-width=\"1.3\"' + (dash ? ' stroke-dasharray=\"4 3\"' : '') + '/>' +\r\n        '<text x=\"' + (xx + (anchor === 'end' ? -4 : 4)).toFixed(1) + '\" y=\"' + ly + '\" font-size=\"9\" fill=\"' + col + '\" font-family=\"monospace\" text-anchor=\"' + (anchor || 'start') + '\">' + label + '<\/text>';\r\n    }\r\n    s += vline(stats.p10, C.jade, 'P10 ' + stats.p10.toFixed(1), true, T + 12);\r\n    s += vline(stats.p90, C.clay, 'P90 ' + stats.p90.toFixed(1), true, T + 12);\r\n    var lowOut = state.plan < lo, highOut = state.plan > hi;\r\n    var closeP50 = !lowOut && !highOut && Math.abs(state.plan - stats.p50) <= 0.6;\r\n    if (closeP50) {\r\n      s += '<line x1=\"' + x(stats.p50).toFixed(1) + '\" y1=\"' + T + '\" x2=\"' + x(stats.p50).toFixed(1) + '\" y2=\"' + (H - B) + '\" stroke=\"' + C.jade + '\" stroke-width=\"1.4\"/>';\r\n      s += '<line x1=\"' + x(state.plan).toFixed(1) + '\" y1=\"' + T + '\" x2=\"' + x(state.plan).toFixed(1) + '\" y2=\"' + (H - B) + '\" stroke=\"' + C.bad + '\" stroke-width=\"1.3\" stroke-dasharray=\"4 3\" opacity=\".55\"/>';\r\n      s += '<text x=\"' + (x(stats.p50) + 4).toFixed(1) + '\" y=\"' + (T + 24) + '\" font-size=\"9\" fill=\"' + C.bad + '\" font-family=\"monospace\">P50 ' + stats.p50.toFixed(1) + ' ≈ 计划 ' + state.plan + ' 天<\/text>';\r\n    } else {\r\n      s += vline(stats.p50, C.jade, 'P50 ' + stats.p50.toFixed(1), false, T + 24);\r\n      if (lowOut) s += vline(state.plan, C.bad, '计划 ' + state.plan + ' 天 · 低于全部样本', false, T + 36, 'start', L);\r\n      else if (highOut) s += vline(state.plan, C.bad, '计划 ' + state.plan + ' 天 · 高于全部样本', false, T + 36, 'end', W - R);\r\n      else s += vline(state.plan, C.bad, '计划 ' + state.plan + ' 天', false, T + 36);\r\n    }\r\n    el('hist').innerHTML = s;\r\n  }\r\n\r\n  function drawCdf(sorted, stats) {\r\n    var W = 680, H = 108, L = 38, R = 14, T = 10, B = 22;\r\n    var min = sorted[0], max = sorted[sorted.length - 1];\r\n    function x(v) { return L + (v - min) / Math.max(0.01, max - min) * (W - L - R); }\r\n    function y(p) { return T + (1 - p) * (H - T - B); }\r\n    var s = '', i, t;\r\n    [0, 0.25, 0.5, 0.75, 1].forEach(function (p) {\r\n      s += '<line x1=\"' + L + '\" y1=\"' + y(p) + '\" x2=\"' + (W - R) + '\" y2=\"' + y(p) + '\" stroke=\"#eee8da\"/>';\r\n      s += '<text x=\"' + (L - 5) + '\" y=\"' + (y(p) + 3) + '\" text-anchor=\"end\" font-size=\"8\" font-family=\"monospace\" fill=\"#98a199\">' + Math.round(p * 100) + '%<\/text>';\r\n    });\r\n    for (t = 0; t <= 4; t++) {\r\n      var vv = min + (max - min) * t / 4;\r\n      s += '<line x1=\"' + x(vv) + '\" y1=\"' + (H - B) + '\" x2=\"' + x(vv) + '\" y2=\"' + (H - B + 4) + '\" stroke=\"#cbbfa7\"/>';\r\n      s += '<text x=\"' + x(vv) + '\" y=\"' + (H - B + 13) + '\" text-anchor=\"middle\" font-size=\"8\" font-family=\"monospace\" fill=\"#98a199\">' + vv.toFixed(0) + '<\/text>';\r\n    }\r\n    var d = '', area = 'M' + x(min) + ' ' + y(0);\r\n    for (i = 0; i <= 160; i++) {\r\n      var v = min + (max - min) * i / 160;\r\n      var p = inCdf(sorted, v);\r\n      d += (i ? 'L' : 'M') + x(v).toFixed(1) + ' ' + y(p).toFixed(1);\r\n      area += 'L' + x(v).toFixed(1) + ' ' + y(p).toFixed(1);\r\n    }\r\n    area += 'L' + x(max) + ' ' + y(0) + 'Z';\r\n    s += '<path d=\"' + area + '\" fill=\"rgba(18,59,58,.08)\"/>';\r\n    s += '<path d=\"' + d + '\" fill=\"none\" stroke=\"#123b3a\" stroke-width=\"1.8\"/>';\r\n    [[stats.p50, 'P50'], [stats.p90, 'P90']].forEach(function (m) {\r\n      s += '<line x1=\"' + x(m[0]) + '\" y1=\"' + T + '\" x2=\"' + x(m[0]) + '\" y2=\"' + (H - B) + '\" stroke=\"#b4762a\" stroke-width=\".8\" stroke-dasharray=\"3 3\" opacity=\".55\"/>';\r\n      s += '<text x=\"' + x(m[0]) + '\" y=\"' + (H - B - 3) + '\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8a5718\" font-family=\"monospace\">' + m[1] + '<\/text>';\r\n    });\r\n    var px = x(Math.max(min, Math.min(max, state.plan)));\r\n    var pp = inCdf(sorted, state.plan);\r\n    s += '<line x1=\"' + px + '\" y1=\"' + T + '\" x2=\"' + px + '\" y2=\"' + (H - B) + '\" stroke=\"#9c4235\" stroke-width=\"1.2\" stroke-dasharray=\"4 3\"/>';\r\n    s += '<circle cx=\"' + px + '\" cy=\"' + y(pp) + '\" r=\"3.4\" fill=\"#fbf8f0\" stroke=\"#9c4235\" stroke-width=\"1.8\"/>';\r\n    s += '<text x=\"' + Math.min(px + 6, W - R - 92) + '\" y=\"' + Math.max(T + 10, y(pp) - 7) + '\" font-size=\"9\" fill=\"#9c4235\">计划 ' + state.plan + ' 天 · ' + Math.round(pp * 100) + '%<\/text>';\r\n    el('cdf').innerHTML = s;\r\n  }\r\n\r\n  function drawLoss() {\r\n    var svg = el('curve');\r\n    if (!svg) return;\r\n    var W = 320, H = 54, L = 26, R = 30, T = 5, B = 11;\r\n    var hist = MODEL.hist, vhist = MODEL.vhist;\r\n    var all = hist.concat(vhist);\r\n    var lo = Math.min.apply(null, all), hi = Math.max.apply(null, all);\r\n    var pad = (hi - lo) * 0.15 || 0.005;\r\n    lo = Math.max(0, lo - pad); hi += pad;\r\n    function X(i) { return L + i * (W - L - R) / Math.max(1, hist.length - 1); }\r\n    function Y(v) { return T + (1 - (v - lo) / (hi - lo)) * (H - T - B); }\r\n    var s = '';\r\n    [0, 0.5, 1].forEach(function (t) {\r\n      var v = lo + (hi - lo) * t, yy = Y(v);\r\n      s += '<line x1=\"' + L + '\" y1=\"' + yy + '\" x2=\"' + (W - R) + '\" y2=\"' + yy + '\" stroke=\"#efece1\"/>' +\r\n        '<text x=\"' + (L - 3) + '\" y=\"' + (yy + 3) + '\" text-anchor=\"end\" font-size=\"7\" font-family=\"monospace\" fill=\"#99a3a4\">' + v.toFixed(3) + '<\/text>';\r\n    });\r\n    function path(arr) {\r\n      return arr.map(function (v, i) { return (i ? 'L' : 'M') + X(i).toFixed(1) + ' ' + Y(v).toFixed(1); }).join('');\r\n    }\r\n    s += '<path d=\"' + path(hist) + '\" fill=\"none\" stroke=\"#1d4e50\" stroke-width=\"1.6\"/>';\r\n    s += '<path d=\"' + path(vhist) + '\" fill=\"none\" stroke=\"#a9742c\" stroke-width=\"1.3\" stroke-dasharray=\"3 2\"/>';\r\n    var y1 = Y(hist[hist.length - 1]), y2 = Y(vhist[vhist.length - 1]);\r\n    if (Math.abs(y1 - y2) < 8) { y1 -= 4; y2 += 6; }\r\n    s += '<text x=\"' + (W - R + 3) + '\" y=\"' + (y1 + 2.5) + '\" font-size=\"7\" fill=\"#1d4e50\">训练<\/text>';\r\n    s += '<text x=\"' + (W - R + 3) + '\" y=\"' + (y2 + 2.5) + '\" font-size=\"7\" fill=\"#a9742c\">验证<\/text>';\r\n    s += '<text x=\"' + L + '\" y=\"' + (H - 1) + '\" font-size=\"7\" font-family=\"monospace\" fill=\"#99a3a4\">0<\/text>';\r\n    s += '<text x=\"' + (W - R) + '\" y=\"' + (H - 1) + '\" text-anchor=\"end\" font-size=\"7\" font-family=\"monospace\" fill=\"#99a3a4\">' + EP + ' 轮<\/text>';\r\n    svg.innerHTML = s;\r\n  }\r\n\r\n  function drawCalib() {\r\n    var svg = el('calib');\r\n    if (!svg) return;\r\n    var W = 320, H = 78, L = 28, R = 8, T = 6, B = 16;\r\n    var maxV = 0;\r\n    MODEL.calib.forEach(function (d) { maxV = Math.max(maxV, d.pred, d.act); });\r\n    maxV = Math.max(1, Math.ceil(maxV * 1.12 * 2) / 2);\r\n    function X(v) { return L + v / maxV * (W - L - R); }\r\n    function Y(v) { return T + (1 - v / maxV) * (H - T - B); }\r\n    var s = '', i;\r\n    for (i = 1; i <= 3; i++) {\r\n      var gv = maxV * i / 4;\r\n      s += '<line x1=\"' + X(gv) + '\" y1=\"' + T + '\" x2=\"' + X(gv) + '\" y2=\"' + (H - B) + '\" stroke=\"#f0ede4\"/>';\r\n      s += '<line x1=\"' + L + '\" y1=\"' + Y(gv) + '\" x2=\"' + (W - R) + '\" y2=\"' + Y(gv) + '\" stroke=\"#f0ede4\"/>';\r\n    }\r\n    s += '<line x1=\"' + L + '\" y1=\"' + (H - B) + '\" x2=\"' + (W - R) + '\" y2=\"' + (H - B) + '\" stroke=\"#d3c9b6\"/>';\r\n    s += '<line x1=\"' + L + '\" y1=\"' + T + '\" x2=\"' + L + '\" y2=\"' + (H - B) + '\" stroke=\"#d3c9b6\"/>';\r\n    s += '<line x1=\"' + X(0) + '\" y1=\"' + Y(0) + '\" x2=\"' + X(maxV) + '\" y2=\"' + Y(maxV) + '\" stroke=\"#b4762a\" stroke-width=\"1\" stroke-dasharray=\"4 3\" opacity=\".7\"/>';\r\n    var pts = MODEL.calib.map(function (d) { return X(d.pred).toFixed(1) + ',' + Y(d.act).toFixed(1); });\r\n    s += '<path d=\"M' + pts.join('L') + '\" fill=\"none\" stroke=\"#1d4e50\" stroke-width=\"1.2\" opacity=\".55\"/>';\r\n    MODEL.calib.forEach(function (d) {\r\n      s += '<circle cx=\"' + X(d.pred).toFixed(1) + '\" cy=\"' + Y(d.act).toFixed(1) + '\" r=\"2.6\" fill=\"#fbf8f0\" stroke=\"#1d4e50\" stroke-width=\"1.5\"/>';\r\n    });\r\n    s += '<text x=\"' + (L + 2) + '\" y=\"' + (T + 7) + '\" font-size=\"7\" fill=\"#8a5718\">实际 ↑<\/text>';\r\n    s += '<text x=\"' + (W - R) + '\" y=\"' + (T + 7) + '\" text-anchor=\"end\" font-size=\"7\" fill=\"#8a5718\">预测 →<\/text>';\r\n    s += '<text x=\"' + L + '\" y=\"' + (H - 3) + '\" font-size=\"7\" font-family=\"monospace\" fill=\"#99a3a4\">0<\/text>';\r\n    s += '<text x=\"' + (W - R) + '\" y=\"' + (H - 3) + '\" text-anchor=\"end\" font-size=\"7\" font-family=\"monospace\" fill=\"#99a3a4\">' + maxV.toFixed(1) + ' 天<\/text>';\r\n    svg.innerHTML = s;\r\n  }\r\n\r\n  function drawContrib(groups) {\r\n    var max = 0;\r\n    groups.forEach(function (g) { max = Math.max(max, Math.abs(g.c)); });\r\n    if (max < 1e-6) max = 1;\r\n    el('contrib').innerHTML = groups.map(function (g) {\r\n      var w = Math.abs(g.c) / max * 50;\r\n      var style = g.c >= 0\r\n        ? 'left:50%;width:' + w.toFixed(1) + '%;background:var(--jade)'\r\n        : 'right:50%;width:' + w.toFixed(1) + '%;background:var(--bad)';\r\n      return '<div class=\"grpbar\"><span>' + g.label + '<\/span><span class=\"track\"><i style=\"' + style + '\"><\/i><\/span><span class=\"val\">×' + Math.exp(g.c).toFixed(2) + '<\/span><\/div>';\r\n    }).join('') + '<p class=\"mini\" style=\"margin-top:2px\">×1.00 = 训练集均值井；&gt;1 拉长、&lt;1 缩短。共线作业特征会分摊权重。<\/p>';\r\n  }\r\n\r\n  /* =========================================================\r\n     当前工单 → 预测 → 合成 → 页面\r\n     ========================================================= */\r\n  function currentJob() {\r\n    var f = faultOf(state.fault);\r\n    return {\r\n      depth: state.depth, fault: f, mill: state.mill, kill: state.kill,\r\n      compOp: (state.mill ? 0.6 : 0) + (state.kill ? 0.4 : 0),\r\n      nproc: 7 + (state.mill ? 1 : 0) + (state.kill ? 1 : 0)\r\n    };\r\n  }\r\n\r\n  function standardizeJob(job) {\r\n    var raw = feats(job), z = new Array(D);\r\n    for (var j = 0; j < D; j++) z[j] = (raw[j] - MODEL.mu[j]) / MODEL.sd[j];\r\n    return z;\r\n  }\r\n\r\n  function setBar(id, z) {\r\n    var b = el(id);\r\n    if (!b) return;\r\n    var w = Math.min(50, Math.abs(z) / 2.5 * 50);\r\n    b.style.width = w.toFixed(1) + '%';\r\n    if (z >= 0) { b.style.left = '50%'; b.style.right = 'auto'; }\r\n    else { b.style.right = '50%'; b.style.left = 'auto'; }\r\n    b.style.background = z >= 0 ? 'var(--jade)' : 'var(--bad)';\r\n  }\r\n\r\n  function render() {\r\n    var job = currentJob();\r\n    var x = standardizeJob(job);\r\n    var preds = predictFromX(x, MODEL.models);\r\n    var res = simulate(preds, MC_N);\r\n    var stats = statsOf(res.totals, state.plan);\r\n    var indepStats = statsOf(simulateTotals(preds, MC_N, true), state.plan);\r\n    var shares = sharesOf(res);\r\n    var keyIdx = 0, i, j;\r\n    for (i = 1; i < 7; i++) if (shares[i] > shares[keyIdx]) keyIdx = i;\r\n    var corrSum = 0, corrN = 0;\r\n    for (i = 0; i < 7; i++) for (j = i + 1; j < 7; j++) { corrSum += corrOf(res.per[i], res.per[j]); corrN++; }\r\n    var corrAvg = corrSum / corrN;\r\n    var pct = stats.prob >= 1 ? 100 : Math.min(99, Math.round(stats.prob * 100));\r\n\r\n    /* 头部 */\r\n    el('st-p50').innerHTML = stats.p50.toFixed(1) + '<small>天<\/small>';\r\n    el('st-p90').innerHTML = stats.p90.toFixed(1) + '<small>天<\/small>';\r\n    el('st-prob').innerHTML = pct + '<small>%<\/small>';\r\n    el('st-w').innerHTML = (stats.p90 - stats.p10).toFixed(1) + '<small>天<\/small>';\r\n    el('mc-hint').textContent = '2000 次 · 共同因子 0.60 / 平均相关 ' + corrAvg.toFixed(2) + ' · 均值 ' + stats.mean.toFixed(1) + ' 天';\r\n\r\n    /* 左列主画布 */\r\n    drawGantt(res, stats, keyIdx);\r\n    drawHist(stats.sorted, stats);\r\n    drawCdf(stats.sorted, stats);\r\n\r\n    /* 01 采集与质控 */\r\n    el('q-bad').textContent = DATA.qc.bad;\r\n    el('q-miss').textContent = DATA.qc.miss;\r\n    el('q-trunc').textContent = DATA.qc.trunc;\r\n    el('q-ok').textContent = DATA.qc.ok;\r\n    el('q-rate').textContent = (DATA.qc.ok / DATA.qc.raw * 100).toFixed(1) + '%';\r\n    el('q-split').textContent = MODEL.nTrain + ' / ' + MODEL.nVal;\r\n    el('q-cur').innerHTML = job.depth + ' m · ' + job.fault.name + ' · ' + (job.mill ? '磨铣' : '不磨铣') + (job.kill ? '+压井' : '') + ' · ' + job.nproc + ' 道工序';\r\n    el('q-gate').innerHTML = '<span class=\"db ok\">可用 · 进入特征<\/span>';\r\n\r\n    /* 02 特征 */\r\n    var raw = feats(job);\r\n    el('fv-depth').textContent = raw[0].toFixed(2) + ' km (z ' + (x[0] >= 0 ? '+' : '') + x[0].toFixed(2) + ')';\r\n    setBar('fb-depth', x[0]);\r\n    el('f-onehot').innerHTML = FAULTS.map(function (f) {\r\n      var on = job.fault.key === f.key;\r\n      return '<span class=\"chip' + (on ? ' on' : '') + '\">' + f.name + ' ' + (on ? 1 : 0) + '<\/span>';\r\n    }).join('');\r\n    el('fv-comp').textContent = raw[5].toFixed(2) + ' (z ' + (x[5] >= 0 ? '+' : '') + x[5].toFixed(2) + ')';\r\n    setBar('fb-comp', x[5]);\r\n    el('fv-nproc').textContent = raw[6] + ' 道 (z ' + (x[6] >= 0 ? '+' : '') + x[6].toFixed(2) + ')';\r\n    setBar('fb-nproc', x[6]);\r\n    el('fv-fish').textContent = raw[1] + ' (z ' + (x[1] >= 0 ? '+' : '') + x[1].toFixed(2) + ')';\r\n    setBar('fb-fish', x[1]);\r\n    el('fv-casing').textContent = raw[2] + ' (z ' + (x[2] >= 0 ? '+' : '') + x[2].toFixed(2) + ')';\r\n    setBar('fb-casing', x[2]);\r\n    el('fv-mill').textContent = raw[7] + ' (z ' + (x[7] >= 0 ? '+' : '') + x[7].toFixed(2) + ')';\r\n    setBar('fb-mill', x[7]);\r\n    el('fv-kill').textContent = raw[8] + ' (z ' + (x[8] >= 0 ? '+' : '') + x[8].toFixed(2) + ')';\r\n    setBar('fb-kill', x[8]);\r\n\r\n    /* 03 模型指标 + 当前贡献 */\r\n    el('m-n').textContent = MODEL.nTrain + ' / ' + MODEL.nVal;\r\n    el('m-cov').innerHTML = (MODEL.coverage * 100).toFixed(1) + '%';\r\n    el('m-ae').innerHTML = MODEL.medAE.toFixed(2) + ' 天';\r\n    el('m-cross').textContent = MODEL.cross + ' 条';\r\n    el('m-summary').innerHTML = '覆盖 <b>' + (MODEL.coverage * 100).toFixed(1) + '%<\/b> · P50 误差 <b>' + MODEL.medAE.toFixed(2) + ' 天<\/b> · 总工期误差 ' + MODEL.totalMedAE.toFixed(1) + ' 天';\r\n    var mP50 = MODEL.models[keyIdx * 3 + 1];\r\n    var gDepth = mP50.w[0] * x[0];\r\n    var gFault = mP50.w[1] * x[1] + mP50.w[2] * x[2] + mP50.w[3] * x[3] + mP50.w[4] * x[4];\r\n    var gOp = mP50.w[5] * x[5] + mP50.w[6] * x[6] + mP50.w[7] * x[7] + mP50.w[8] * x[8];\r\n    drawContrib([\r\n      { label: '井深', c: gDepth },\r\n      { label: '故障类型', c: gFault },\r\n      { label: '作业复杂度', c: gOp }\r\n    ]);\r\n\r\n    /* 04 工序分位与合成参数 */\r\n    el('s-corr').textContent = corrAvg.toFixed(2);\r\n    el('s-indep').textContent = '−' + Math.max(0, (stats.p90 - stats.p10) - (indepStats.p90 - indepStats.p10)).toFixed(1) + ' 天';\r\n    var rows = '';\r\n    for (i = 0; i < 7; i++) {\r\n      var d = preds[i], isKey = i === keyIdx;\r\n      rows += '<tr' + (isKey ? ' class=\"keep\"' : '') + '><td>' + PROCS[i].name + (isKey ? ' <span class=\"db warn\">方差 ' + Math.round(shares[i] * 100) + '%<\/span>' : '') + '<\/td>' +\r\n        '<td class=\"num\">' + d.p10.toFixed(1) + '<\/td><td class=\"num\">' + d.p50.toFixed(1) + '<\/td><td class=\"num\">' + d.p90.toFixed(1) + '<\/td>' +\r\n        '<td class=\"num\">' + (d.p90 - d.p10).toFixed(1) + '<\/td><\/tr>';\r\n    }\r\n    rows += '<tr><td><b>合计<\/b><\/td><td class=\"num\">' + stats.p10.toFixed(1) + '<\/td><td class=\"num\">' + stats.p50.toFixed(1) +\r\n      '<\/td><td class=\"num\">' + stats.p90.toFixed(1) + '<\/td><td class=\"num\">' + (stats.p90 - stats.p10).toFixed(1) + '<\/td><\/tr>';\r\n    el('proc').innerHTML = rows;\r\n    el('key-hint').innerHTML = '总工期方差 <b>' + Math.round(shares[keyIdx] * 100) + '%<\/b> 来自 <b>' + PROCS[keyIdx].name + '<\/b>（P10—P90 宽 ' +\r\n      (preds[keyIdx].p90 - preds[keyIdx].p10).toFixed(1) + ' 天）；压缩它的区间比把每道工序都估准更有效。';\r\n\r\n    /* 05 计划决策 */\r\n    el('p-plan').textContent = state.plan + ' 天';\r\n    el('p-prob').innerHTML = pct + '%';\r\n    el('p-p80').textContent = stats.p80.toFixed(1) + ' 天';\r\n    el('p-key').textContent = PROCS[keyIdx].name;\r\n    var marks = [\r\n      { k: '当前计划', v: state.plan },\r\n      { k: 'P50', v: stats.p50 },\r\n      { k: 'P80', v: stats.p80 },\r\n      { k: 'P90', v: stats.p90 }\r\n    ];\r\n    el('plantab').innerHTML = marks.map(function (m) {\r\n      var pr = inCdf(stats.sorted, m.v);\r\n      return '<tr><td class=\"k2\">' + m.k + '<\/td><td class=\"num\">' + m.v.toFixed(1) + ' 天<\/td><td class=\"num\"><b>' + Math.round(pr * 100) + '%<\/b><\/td><\/tr>';\r\n    }).join('');\r\n\r\n    /* 结论 */\r\n    var gain1 = (inCdf(stats.sorted, state.plan + 1) - inCdf(stats.sorted, state.plan)) * 100;\r\n    var planMsg;\r\n    if (state.plan < stats.p10) {\r\n      planMsg = '计划 <b>' + state.plan + ' 天<\/b> 低于 P10（' + stats.p10.toFixed(1) + ' 天），几乎必然超期。';\r\n    } else if (state.plan < stats.p50) {\r\n      planMsg = '计划 <b>' + state.plan + ' 天<\/b> 低于 P50（' + stats.p50.toFixed(1) + ' 天），按期概率不到一半；每增加 1 天约 +' + gain1.toFixed(1) + ' 个百分点。';\r\n    } else if (state.plan <= stats.p90) {\r\n      planMsg = '计划处于 P50—P90 之间：每增加 1 天约 +' + gain1.toFixed(1) + ' 个百分点；P80 = <b>' + stats.p80.toFixed(1) + ' 天<\/b> 覆盖约 80%。';\r\n    } else {\r\n      planMsg = '计划 <b>' + state.plan + ' 天<\/b> 高于 P90（' + stats.p90.toFixed(1) + ' 天），余量偏宽，可回收到 P80 = <b>' + stats.p80.toFixed(1) + ' 天<\/b>。';\r\n    }\r\n    el('note').innerHTML = '总工期的方差 <b>' + Math.round(shares[keyIdx] * 100) + '%<\/b> 来自 <b>' + PROCS[keyIdx].name + '<\/b>（P10—P90 宽 ' +\r\n      (preds[keyIdx].p90 - preds[keyIdx].p10).toFixed(1) + ' 天）。' + planMsg +\r\n      ' <span style=\"color:var(--ink-4)\">1450 井次与价值数字为示范口径，不是本页仿真读数。<\/span>';\r\n\r\n    LAST = {\r\n      job: job, x: x, preds: preds, res: res, stats: stats, indepStats: indepStats,\r\n      shares: shares, keyIdx: keyIdx, corrAvg: corrAvg, pct: pct\r\n    };\r\n    return LAST;\r\n  }\r\n\r\n  /* =========================================================\r\n     过程日志 / 阶段轨\r\n     ========================================================= */\r\n  var TRACE = [];\r\n  function trace(step, html, cls) {\r\n    TRACE.push({ step: step, html: html, cls: cls || '' });\r\n    if (TRACE.length > 8) TRACE.shift();\r\n    var box = el('trace');\r\n    box.innerHTML = TRACE.map(function (t) {\r\n      return '<div><span class=\"t\">' + t.step + '<\/span><span class=\"' + t.cls + '\">' + t.html + '<\/span><\/div>';\r\n    }).join('');\r\n    box.scrollTop = box.scrollHeight;\r\n  }\r\n  function clearTrace() {\r\n    TRACE = [];\r\n    el('trace').innerHTML = '<div><span class=\"t\">—<\/span><span>等待运行：调井况后点「运行全流程」，或直接点上面的阶段。<\/span><\/div>';\r\n  }\r\n\r\n  var STAGE_LABEL = ['01 采集', '02 特征', '03 模型', '04 合成', '05 决策'];\r\n  var runTimers = [];\r\n  function cancelRun() {\r\n    runTimers.forEach(function (t) { clearTimeout(t); });\r\n    runTimers = [];\r\n    var btn = el('btn-run');\r\n    if (btn) { btn.disabled = false; btn.textContent = '▶ 运行全流程'; }\r\n  }\r\n  function setStage(i, log) {\r\n    [].forEach.call(document.querySelectorAll('.dstage'), function (p) {\r\n      p.classList.toggle('on', Number(p.getAttribute('data-stage')) === i);\r\n    });\r\n    [].forEach.call(el('flow').children, function (b, idx) {\r\n      b.classList.toggle('on', idx === i);\r\n      b.classList.toggle('done', idx < i);\r\n      b.setAttribute('aria-selected', idx === i ? 'true' : 'false');\r\n    });\r\n    if (log) trace(STAGE_LABEL[i].slice(0, 2), log);\r\n  }\r\n\r\n  function runAll() {\r\n    cancelRun();\r\n    var L = render();\r\n    clearTrace();\r\n    var btn = el('btn-run');\r\n    btn.disabled = true;\r\n    btn.textContent = '运行中…';\r\n    var key = PROCS[L.keyIdx].name;\r\n    var kp = L.preds[L.keyIdx];\r\n    var steps = [\r\n      ['01', '读取 <b>1450<\/b> 井次工单 · 质控剔除 <b>128<\/b> 条（异常 47 / 缺工序 51 / 截断 30）· 可用 <b>1322<\/b> 条'],\r\n      ['02', '当前工单 → <b>9<\/b> 维特征 · 井深 <b>' + (L.job.depth / 1000).toFixed(2) + ' km<\/b> · 故障 <b>' + L.job.fault.name + '<\/b> · 复杂度 <b>' + L.job.compOp.toFixed(2) + '<\/b> · 工序数 <b>' + L.job.nproc + '<\/b>'],\r\n      ['03', '21 组分位数回归推理 · ' + key + ' P10/P50/P90 = <b>' + kp.p10.toFixed(1) + ' / ' + kp.p50.toFixed(1) + ' / ' + kp.p90.toFixed(1) + ' 天<\/b> · 验证覆盖 <b>' + (MODEL.coverage * 100).toFixed(1) + '%<\/b>'],\r\n      ['04', '2000 次 MC 合成 · P50 <b>' + L.stats.p50.toFixed(1) + ' 天<\/b> · P90 <b>' + L.stats.p90.toFixed(1) + ' 天<\/b> · 计划 ' + state.plan + ' 天按期 <b>' + L.pct + '%<\/b>'],\r\n      ['05', '计划 <b>' + state.plan + ' 天<\/b> · P80 <b>' + L.stats.p80.toFixed(1) + ' 天<\/b> · 建议按 P80 承诺；人工确认后回写台账']\r\n    ];\r\n    var delays = [0, 800, 1600, 2400, 3200];\r\n    steps.forEach(function (s, i) {\r\n      runTimers.push(setTimeout(function () {\r\n        setStage(i, null);\r\n        trace(s[0], s[1]);\r\n        if (i === steps.length - 1) {\r\n          runTimers.push(setTimeout(function () {\r\n            btn.disabled = false;\r\n            btn.textContent = '▶ 重新运行';\r\n            trace('✓', '流水线完成：从 1450 井次历史工单到一条可承诺的工期。', 'ok');\r\n          }, 700));\r\n        }\r\n      }, delays[i]));\r\n    });\r\n  }\r\n\r\n  /* =========================================================\r\n     控件\r\n     ========================================================= */\r\n  function syncControls() {\r\n    el('r-depth').value = state.depth;\r\n    el('o-depth').textContent = state.depth + ' m';\r\n    el('r-plan').value = state.plan;\r\n    el('o-plan').textContent = state.plan + ' 天';\r\n    [].forEach.call(el('seg-fault').children, function (b) {\r\n      var on = b.getAttribute('data-f') === state.fault;\r\n      b.classList.toggle('on', on);\r\n      b.setAttribute('aria-pressed', on ? 'true' : 'false');\r\n    });\r\n    [['tog-mill', 'mill'], ['tog-kill', 'kill']].forEach(function (p) {\r\n      var t = el(p[0]);\r\n      t.classList.toggle('on', state[p[1]]);\r\n      t.setAttribute('aria-checked', state[p[1]] ? 'true' : 'false');\r\n    });\r\n  }\r\n\r\n  function syncPlan() {\r\n    el('r-plan').value = state.plan;\r\n    el('o-plan').textContent = state.plan + ' 天';\r\n  }\r\n\r\n  function updateFbNote() {\r\n    var n = fb.adopt + fb.adjust;\r\n    el('fb-note').textContent = '回写 ' + n + ' 条' + (n ? ' · 采纳 ' + fb.adopt + ' / 人工改期 ' + fb.adjust : '') + ' · 人工确认后才进入下一轮训练';\r\n  }\r\n\r\n  el('seg-fault').innerHTML = FAULTS.map(function (f) {\r\n    var on = f.key === state.fault;\r\n    return '<button type=\"button\" data-f=\"' + f.key + '\" class=\"' + (on ? 'on' : '') + '\" aria-pressed=\"' + (on ? 'true' : 'false') + '\" aria-label=\"故障类型：' + f.name + '\">' + f.name + '<\/button>';\r\n  }).join('');\r\n\r\n  el('seg-fault').addEventListener('click', function (e) {\r\n    var b = e.target.closest('button'); if (!b) return;\r\n    cancelRun();\r\n    state.fault = b.getAttribute('data-f');\r\n    syncControls();\r\n    var L = render();\r\n    trace('工单', '故障类型 → <b>' + L.job.fault.name + '<\/b> · 9 维特征重算 · P50 <b>' + L.stats.p50.toFixed(1) + ' 天<\/b>');\r\n  });\r\n\r\n  el('r-depth').addEventListener('input', function () {\r\n    cancelRun();\r\n    state.depth = Number(el('r-depth').value);\r\n    el('o-depth').textContent = state.depth + ' m';\r\n    render();\r\n  });\r\n  el('r-depth').addEventListener('change', function () {\r\n    var L = LAST;\r\n    trace('工单', '井深 → <b>' + state.depth + ' m<\/b> · 分位与 MC 重算 · P50 <b>' + L.stats.p50.toFixed(1) + ' 天<\/b>');\r\n  });\r\n\r\n  el('r-plan').addEventListener('input', function () {\r\n    cancelRun();\r\n    state.plan = Number(el('r-plan').value);\r\n    el('o-plan').textContent = state.plan + ' 天';\r\n    render();\r\n  });\r\n  el('r-plan').addEventListener('change', function () {\r\n    var L = LAST;\r\n    trace('计划', '计划工期 → <b>' + state.plan + ' 天<\/b> · 按期概率 <b>' + L.pct + '%<\/b>');\r\n  });\r\n\r\n  [['tog-mill', 'mill'], ['tog-kill', 'kill']].forEach(function (p) {\r\n    var t = el(p[0]);\r\n    t.addEventListener('click', function () {\r\n      cancelRun();\r\n      state[p[1]] = !state[p[1]];\r\n      syncControls();\r\n      var L = render();\r\n      trace('工单', (p[1] === 'mill' ? '磨铣' : '压井') + ' → <b>' + (state[p[1]] ? '是' : '否') + '<\/b> · 复杂度 <b>' + L.job.compOp.toFixed(2) + '<\/b> · P50 <b>' + L.stats.p50.toFixed(1) + ' 天<\/b>');\r\n    });\r\n  });\r\n\r\n  el('btn-run').addEventListener('click', runAll);\r\n\r\n  el('btn-reset').addEventListener('click', function () {\r\n    cancelRun();\r\n    state.fault = DEFAULTS.fault;\r\n    state.depth = DEFAULTS.depth;\r\n    state.mill = DEFAULTS.mill;\r\n    state.kill = DEFAULTS.kill;\r\n    state.plan = DEFAULTS.plan;\r\n    fb = { adopt: 0, adjust: 0 };\r\n    syncControls();\r\n    updateFbNote();\r\n    setStage(0, false);\r\n    clearTrace();\r\n    render();\r\n  });\r\n\r\n  el('flow').addEventListener('click', function (e) {\r\n    var b = e.target.closest('button'); if (!b) return;\r\n    cancelRun();\r\n    setStage(Number(b.getAttribute('data-s')), null);\r\n  });\r\n\r\n  el('feedback').addEventListener('click', function (e) {\r\n    var b = e.target.closest('button'); if (!b) return;\r\n    var k = b.getAttribute('data-fb');\r\n    if (k === 'adopt') {\r\n      var p80 = Math.round(LAST.stats.p80 * 2) / 2;\r\n      state.plan = Math.max(3, Math.min(20, p80));\r\n      syncPlan();\r\n      render();\r\n      fb.adopt++;\r\n      trace('回写', '采纳 P80 承诺 <b>' + state.plan + ' 天<\/b> · 覆盖约 80% 抽样 · 已回写台账', 'ok');\r\n    } else {\r\n      state.plan = Math.min(20, state.plan + 1);\r\n      syncPlan();\r\n      render();\r\n      fb.adjust++;\r\n      trace('回写', '人工上调计划至 <b>' + state.plan + ' 天<\/b> · 调整原因进入下一轮复盘', 'warn');\r\n    }\r\n    updateFbNote();\r\n  });\r\n\r\n  /* ---------------- 启动 ---------------- */\r\n  drawLoss();\r\n  drawCalib();\r\n  syncControls();\r\n  updateFbNote();\r\n  clearTrace();\r\n  render();\r\n  setStage(0, false);\r\n  trace('系统', '模型已在本页训练：<b>' + MODEL.nTrain + '<\/b> 训练 / <b>' + MODEL.nVal + '<\/b> 验证 · 21 组模型 · P10—P90 覆盖 <b>' + (MODEL.coverage * 100).toFixed(1) + '%<\/b>', 'ok');\r\n\r\n  /* 供开发期自检读取 */\r\n  window.__WO = {\r\n    MODEL: MODEL, DATA: DATA, state: state,\r\n    get last() { return LAST; }\r\n  };\r\n})();\r\n"},{"name":"demo/index.html","size":18751,"mime":"text/plain","enc":"text","data":"<!DOCTYPE html>\r\n<html lang=\"zh-CN\">\r\n<head>\r\n<meta charset=\"UTF-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n<title>示范：从历史工单到可承诺工期（分位数回归 + 蒙特卡洛）<\/title>\r\n<link rel=\"stylesheet\" href=\"demo.css\">\r\n<style>\r\n  .gantt-wrap{border:1px solid var(--line);border-radius:8px;background:#fff;padding:6px 4px 2px}\r\n  .gantt-wrap svg{display:block;width:100%;height:auto}\r\n  .vrow{display:flex;align-items:baseline;justify-content:space-between;gap:10px;padding:3.5px 0;border-bottom:1px solid var(--line);font-size:10.5px}\r\n  .vrow:last-child{border-bottom:0}\r\n  .vrow .vk{font-family:var(--mono);font-size:8.5px;letter-spacing:.06em;color:var(--ink-4);white-space:nowrap}\r\n  .vrow .vv{font-family:var(--mono);font-size:10.5px;color:var(--ink);text-align:right}\r\n  .vrow .vv small{font-family:var(--sans);font-size:9px;color:var(--ink-4);margin-left:2px}\r\n  .vrow .vv.ok{color:var(--ok)}.vrow .vv.warn{color:var(--warn)}.vrow .vv.bad{color:var(--bad)}\r\n  .frow{display:grid;grid-template-columns:74px minmax(0,1fr) 60px;gap:7px;align-items:center;\r\n    font-size:10px;color:var(--ink-3);padding:3px 0}\r\n  .frow .lb{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\r\n  .frow .track{height:6px;border-radius:3px;background:var(--paper-3);position:relative}\r\n  .frow .track::before{content:'';position:absolute;left:50%;top:-2px;bottom:-2px;width:1px;background:var(--line-2)}\r\n  .frow .track i{position:absolute;top:0;bottom:0;border-radius:3px}\r\n  .frow .val{font-family:var(--mono);font-size:9px;text-align:right;color:var(--ink-2);white-space:nowrap}\r\n  .chips{display:flex;gap:4px;flex-wrap:wrap;padding:2px 0 5px}\r\n  .chip{font-family:var(--mono);font-size:8.5px;padding:1px 5px;border-radius:3px;border:1px solid var(--line-2);color:var(--ink-4)}\r\n  .chip.on{background:var(--jade-l);border-color:var(--jade);color:var(--jade-d)}\r\n  .calwrap{border:1px solid var(--line);border-radius:6px;background:#fff;padding:3px}\r\n  .calwrap svg{display:block;width:100%;height:auto}\r\n  .grpbar{display:grid;grid-template-columns:64px minmax(0,1fr) 52px;gap:7px;align-items:center;font-size:10px;color:var(--ink-3);padding:3px 0}\r\n  .grpbar .track{height:7px;border-radius:3px;background:var(--paper-3);position:relative}\r\n  .grpbar .track::before{content:'';position:absolute;left:50%;top:-2px;bottom:-2px;width:1px;background:var(--line-2)}\r\n  .grpbar .track i{position:absolute;top:0;bottom:0;border-radius:3px}\r\n  .grpbar .val{font-family:var(--mono);font-size:9px;text-align:right;color:var(--ink-2)}\r\n  .plantab td{font-family:var(--mono);font-size:10px;padding:4px 8px 4px 0}\r\n  .plantab .k2{font-family:var(--sans)}\r\n  .valtab td{font-family:var(--mono);font-size:10px;padding:4px 8px 4px 0}\r\n  .valtab .k2{font-family:var(--sans)}\r\n  .valtab .up{color:var(--ok);font-weight:600}\r\n  .mini{font-family:var(--mono);font-size:8.5px;color:var(--ink-4);line-height:1.55}\r\n  .keep{background:var(--jade-l)}\r\n  .dstage .dtable td{padding:1.5px 8px 1.5px 0;font-size:10px}\r\n  .dstage .dtable th{padding:2px 8px 2px 0;font-size:8px}\r\n  .dstage .dval > div{padding:3px 8px}\r\n  .dstage .dval .v{font-size:12.5px}\r\n  .dstage .dval .s{font-size:8.5px}\r\n  .dstage .dfig-h{margin-bottom:5px}\r\n  .dstage-lede{margin:2px 0 5px;font-size:11px;line-height:1.6}\r\n  .dfig-foot{font-size:10px;padding-top:5px;margin-top:6px}\r\n  .dmodel{padding:7px 11px 6px}\r\n  .dmodel-row{padding:3.5px 0;font-size:10px}\r\n  .dtrace{max-height:100px;font-size:9px;line-height:1.7}\r\n  .dfeed .dbtn{padding:3px 8px;font-size:10px}\r\n  .dctl{gap:8px}\r\n  .dctl input[type=range]{width:100px}\r\n  .dctl .seg button{padding:4px 8px;font-size:11px}\r\n  .dctl .seg button:focus-visible,\r\n  .dctl .tog:focus-visible,\r\n  .dctl .dbtn:focus-visible,\r\n  .ctl-s input:focus-visible{outline:2px solid var(--jade);outline-offset:2px}\r\n  @media (max-width:760px){\r\n    .gantt-wrap{overflow-x:auto;-webkit-overflow-scrolling:touch}\r\n    .gantt-wrap svg{min-width:620px}\r\n    .dctl{gap:10px}\r\n    .dctl .seg{width:100%}\r\n  }\r\n<\/style>\r\n<\/head>\r\n<body>\r\n\r\n<div class=\"dhead\">\r\n  <div>\r\n    <div class=\"dkick\">WORKOVER DURATION · 工单 → 特征 → 分位数 → 蒙特卡洛 → 承诺<\/div>\r\n    <h1>从历史工单到可承诺工期：分位数回归 + 蒙特卡洛<\/h1>\r\n    <p class=\"lead\">调度要的不是「这口井大概几天」，而是「按 10 天报计划，按期完工的概率有多大」。示范把 1450 井次历史工单的质控、9 维特征、7 道工序 × P10/P50/P90 分位数回归、2000 次蒙特卡洛合成和计划回写串成一条可运行的流水线。<\/p>\r\n  <\/div>\r\n  <div class=\"dhead-r\">\r\n    <div class=\"dstat\"><div class=\"k\">P50 工期<\/div><div class=\"v\" id=\"st-p50\">—<\/div><\/div>\r\n    <div class=\"dstat\"><div class=\"k\">P90 工期<\/div><div class=\"v\" id=\"st-p90\">—<\/div><\/div>\r\n    <div class=\"dstat good\"><div class=\"k\">按期概率<\/div><div class=\"v\" id=\"st-prob\">—<\/div><\/div>\r\n    <div class=\"dstat\"><div class=\"k\">P10—P90 宽度<\/div><div class=\"v\" id=\"st-w\">—<\/div><\/div>\r\n  <\/div>\r\n<\/div>\r\n\r\n<div class=\"dctl\">\r\n  <div class=\"grp\"><span class=\"glbl\" id=\"lbl-fault\">故障类型<\/span><div class=\"seg\" id=\"seg-fault\" role=\"group\" aria-labelledby=\"lbl-fault\"><\/div><\/div>\r\n  <div class=\"ctl-s\"><label for=\"r-depth\">井深<\/label><input type=\"range\" id=\"r-depth\" min=\"1200\" max=\"3600\" step=\"50\" value=\"2400\" aria-label=\"井深（米）\"><output id=\"o-depth\" for=\"r-depth\">2400 m<\/output><\/div>\r\n  <button type=\"button\" class=\"tog on\" id=\"tog-mill\" role=\"switch\" aria-checked=\"true\" aria-label=\"是否需要磨铣\"><i><\/i>需磨铣<\/button>\r\n  <button type=\"button\" class=\"tog on\" id=\"tog-kill\" role=\"switch\" aria-checked=\"true\" aria-label=\"是否需要压井\"><i><\/i>需压井<\/button>\r\n  <div class=\"ctl-s\"><label for=\"r-plan\">计划工期<\/label><input type=\"range\" id=\"r-plan\" min=\"3\" max=\"20\" step=\"0.5\" value=\"10\" aria-label=\"计划工期（天）\"><output id=\"o-plan\" for=\"r-plan\">10 天<\/output><\/div>\r\n  <div class=\"grp\" style=\"margin-left:auto\">\r\n    <button class=\"dbtn pri\" id=\"btn-run\" type=\"button\">▶ 运行全流程<\/button>\r\n    <button class=\"dbtn\" id=\"btn-reset\" type=\"button\" aria-label=\"恢复默认井况与计划工期\">重置<\/button>\r\n  <\/div>\r\n<\/div>\r\n\r\n<div class=\"dflow\" id=\"flow\" role=\"tablist\" aria-label=\"修井工期 AI 作业流\">\r\n  <button type=\"button\" class=\"on\" data-s=\"0\" role=\"tab\" aria-selected=\"true\"><span class=\"n\"><i>01<\/i>INPUT<\/span><b>工单采集与质控<\/b><span>1450 井次 · 7 道工序<\/span><\/button>\r\n  <button type=\"button\" data-s=\"1\" role=\"tab\" aria-selected=\"false\"><span class=\"n\"><i>02<\/i>FEATURE<\/span><b>模型看到什么<\/b><span>9 维井况特征<\/span><\/button>\r\n  <button type=\"button\" data-s=\"2\" role=\"tab\" aria-selected=\"false\"><span class=\"n\"><i>03<\/i>MODEL<\/span><b>分位数回归<\/b><span>21 组 · 现场训练<\/span><\/button>\r\n  <button type=\"button\" data-s=\"3\" role=\"tab\" aria-selected=\"false\"><span class=\"n\"><i>04<\/i>SIMULATE<\/span><b>蒙特卡洛合成<\/b><span>2000 次 · 共同因子<\/span><\/button>\r\n  <button type=\"button\" data-s=\"4\" role=\"tab\" aria-selected=\"false\"><span class=\"n\"><i>05<\/i>DECIDE<\/span><b>计划与回写<\/b><span>按期率 · 人工调整<\/span><\/button>\r\n<\/div>\r\n\r\n<div class=\"dgrid c2\">\r\n  <div class=\"dcol\">\r\n    <div class=\"dfig\">\r\n      <div class=\"dfig-h\"><b>工序级累计完成时刻（甘特）<\/b><span>横轴：累计天数 · 竖线：总 P50 / P90<\/span><\/div>\r\n      <div class=\"gantt-wrap\"><svg id=\"gantt\" viewBox=\"0 0 680 210\" role=\"img\" aria-label=\"7 道工序的累计完成时刻与总工期分位\"><\/svg><\/div>\r\n      <div class=\"dfig-foot\">\r\n        <span><i style=\"background:#1d4e50\"><\/i>P50 排期段<\/span>\r\n        <span><i style=\"background:#c8dbd2\"><\/i>完成时刻 P10—P90<\/span>\r\n        <span><i style=\"background:#a9742c\"><\/i>方差贡献最大工序<\/span>\r\n        <span><i style=\"background:#1d4e50;height:0;border-left:2px solid #1d4e50;border-radius:0\"><\/i>总 P50 / P90<\/span>\r\n      <\/div>\r\n    <\/div>\r\n    <div class=\"dfig\">\r\n      <div class=\"dfig-h\"><b>总工期分布（2000 次蒙特卡洛）<\/b><span id=\"mc-hint\">—<\/span><\/div>\r\n      <div class=\"gantt-wrap\"><svg id=\"hist\" viewBox=\"0 0 680 165\" role=\"img\" aria-label=\"总工期分布\"><\/svg><\/div>\r\n      <div class=\"dfig-foot\">\r\n        <span><i style=\"background:#c8dbd2\"><\/i>全部落在计划内<\/span>\r\n        <span><i style=\"background:#e6d3ae\"><\/i>跨界 bin<\/span>\r\n        <span><i style=\"background:#a64b3c;opacity:.55\"><\/i>全部超期<\/span>\r\n        <span>竖线：P10 / P50 / P90 与计划工期<\/span>\r\n      <\/div>\r\n    <\/div>\r\n    <div class=\"dfig\">\r\n      <div class=\"dfig-h\"><b>按期完工概率 · CDF<\/b><span>竖线与曲线交点 = 按期概率<\/span><\/div>\r\n      <div class=\"gantt-wrap\"><svg id=\"cdf\" viewBox=\"0 0 680 108\" role=\"img\" aria-label=\"总工期累计概率曲线\"><\/svg><\/div>\r\n    <\/div>\r\n  <\/div>\r\n\r\n  <div class=\"dcol\">\r\n    <div class=\"dfig dstage on\" data-stage=\"0\">\r\n      <div class=\"dfig-h\"><b>01 · 工单采集与质量控制<\/b><span>模型还没开始算<\/span><\/div>\r\n      <p class=\"dstage-lede\">历史工单来自作业管理系统：井深、故障类型、7 道工序起止时间。进模型前先过三道质控：<b>耗时为负/为零<\/b>、<b>7 道缺段<\/b>、<b>总工期被截断<\/b>；不合格工单不进训练集。<\/p>\r\n      <div class=\"vrow\"><span class=\"vk\">原始工单<\/span><span class=\"vv\"><b>1450<\/b> 井次 · 7 道工序<\/span><\/div>\r\n      <div class=\"vrow\"><span class=\"vk\">异常工单<\/span><span class=\"vv\"><b id=\"q-bad\">47<\/b> 条 · 耗时 ≤ 0 / 顺序错<\/span><\/div>\r\n      <div class=\"vrow\"><span class=\"vk\">缺失工序<\/span><span class=\"vv\"><b id=\"q-miss\">51<\/b> 条 · 7 道缺 1<\/span><\/div>\r\n      <div class=\"vrow\"><span class=\"vk\">工期截断<\/span><span class=\"vv\"><b id=\"q-trunc\">30<\/b> 条 · 总工期 &lt; 2.6 天<\/span><\/div>\r\n      <div class=\"vrow\"><span class=\"vk\">质控后可用<\/span><span class=\"vv ok\"><b id=\"q-ok\">1322<\/b> 条 · <b id=\"q-rate\">91.2%<\/b><\/span><\/div>\r\n      <div class=\"vrow\"><span class=\"vk\">训练 / 验证<\/span><span class=\"vv\"><b id=\"q-split\">1058 / 264<\/b> · 80 / 20<\/span><\/div>\r\n      <div class=\"vrow\"><span class=\"vk\">当前工单<\/span><span class=\"vv\" id=\"q-cur\">—<\/span><\/div>\r\n      <div class=\"vrow\"><span class=\"vk\">输入判定<\/span><span class=\"vv\" id=\"q-gate\">—<\/span><\/div>\r\n      <div class=\"dfig-foot\" style=\"margin-top:7px\"><span>截断工单会被系统在 2.6 天「收尾」，如果留在训练集，模型会学会「所有井都很快」。<\/span><\/div>\r\n    <\/div>\r\n\r\n    <div class=\"dfig dstage\" data-stage=\"1\">\r\n      <div class=\"dfig-h\"><b>02 · 模型看到的 9 维特征<\/b><span>原始工单 → 可比较的数<\/span><\/div>\r\n      <p class=\"dstage-lede\">模型不吃「作业队」「天气」这类会随台账变动的字段，只吃 9 个数：<b>井深、5 类故障 one-hot（断脱为基准）、作业复杂度、工序数、含打捞/套管/磨铣/压井<\/b>。每个数按训练集均值标准化。<\/p>\r\n      <div class=\"frow\"><span class=\"lb\">井深<\/span><span class=\"track\"><i id=\"fb-depth\"><\/i><\/span><span class=\"val\" id=\"fv-depth\">—<\/span><\/div>\r\n      <div class=\"chips\" id=\"f-onehot\"><\/div>\r\n      <div class=\"frow\"><span class=\"lb\">作业复杂度<\/span><span class=\"track\"><i id=\"fb-comp\"><\/i><\/span><span class=\"val\" id=\"fv-comp\">—<\/span><\/div>\r\n      <div class=\"frow\"><span class=\"lb\">工序数<\/span><span class=\"track\"><i id=\"fb-nproc\"><\/i><\/span><span class=\"val\" id=\"fv-nproc\">—<\/span><\/div>\r\n      <div class=\"frow\"><span class=\"lb\">含打捞<\/span><span class=\"track\"><i id=\"fb-fish\"><\/i><\/span><span class=\"val\" id=\"fv-fish\">—<\/span><\/div>\r\n      <div class=\"frow\"><span class=\"lb\">含套管作业<\/span><span class=\"track\"><i id=\"fb-casing\"><\/i><\/span><span class=\"val\" id=\"fv-casing\">—<\/span><\/div>\r\n      <div class=\"frow\"><span class=\"lb\">含磨铣<\/span><span class=\"track\"><i id=\"fb-mill\"><\/i><\/span><span class=\"val\" id=\"fv-mill\">—<\/span><\/div>\r\n      <div class=\"frow\"><span class=\"lb\">含压井<\/span><span class=\"track\"><i id=\"fb-kill\"><\/i><\/span><span class=\"val\" id=\"fv-kill\">—<\/span><\/div>\r\n      <div class=\"dfig-foot\" style=\"margin-top:7px\"><span>复杂度 = 磨铣 0.6 + 压井 0.4；工序数 = 7 + 磨铣 + 压井（7—9 道）。<\/span><\/div>\r\n    <\/div>\r\n\r\n    <div class=\"dfig dstage\" data-stage=\"2\">\r\n      <div class=\"dfig-h\"><b>03 · 分位数回归训练与验证<\/b><span>本页现场训练 · 合成工单<\/span><\/div>\r\n      <p class=\"dstage-lede\">7 道工序 × 3 个分位 = <b>21 组线性分位数回归<\/b>，pinball loss 现场训练 200 轮，留出 264 井次验证；分位交叉按单调性后处理。<\/p>\r\n      <div class=\"dval\">\r\n        <div><div class=\"k\">训练 / 验证<\/div><div class=\"v\" id=\"m-n\">—<\/div><div class=\"s\">80 / 20 井次划分<\/div><\/div>\r\n        <div><div class=\"k\">P10—P90 覆盖<\/div><div class=\"v ok\" id=\"m-cov\">—<\/div><div class=\"s\">名义 80%<\/div><\/div>\r\n        <div><div class=\"k\">P50 工序误差<\/div><div class=\"v\" id=\"m-ae\">—<\/div><div class=\"s\">中位绝对误差 · 天<\/div><\/div>\r\n        <div><div class=\"k\">分位交叉<\/div><div class=\"v\" id=\"m-cross\">—<\/div><div class=\"s\">后处理后<\/div><\/div>\r\n      <\/div>\r\n      <p class=\"mini\" style=\"margin:5px 0 1px\">训练损失 · pinball · 每 4 轮<\/p>\r\n      <svg class=\"dcurve\" id=\"curve\" viewBox=\"0 0 320 58\" role=\"img\" aria-label=\"训练与验证损失曲线\"><\/svg>\r\n      <p class=\"mini\" style=\"margin:5px 0 1px\">P50 校准 · 预测 vs 实际（验证集 5 桶中位）<\/p>\r\n      <div class=\"calwrap\"><svg id=\"calib\" viewBox=\"0 0 320 78\" role=\"img\" aria-label=\"P50 预测与实际校准图\"><\/svg><\/div>\r\n      <div class=\"dfig-h\" style=\"margin-top:6px\"><b>当前关键工序的特征贡献<\/b><span>按组汇总 · 对数空间<\/span><\/div>\r\n      <div id=\"contrib\"><\/div>\r\n    <\/div>\r\n\r\n    <div class=\"dfig dstage\" data-stage=\"3\">\r\n      <div class=\"dfig-h\"><b>04 · 蒙特卡洛合成总工期<\/b><span>工序分位 → 总工期分布<\/span><\/div>\r\n      <p class=\"dstage-lede\">每道工序用 P10/P50/P90 拟合对数正态，再按 <b>z_p = 0.60·z₀ + 0.80·ε_p<\/b> 抽 2000 组相加。共同因子代表地层、队伍、设备的共同扰动；去掉它，区间会明显变窄。<\/p>\r\n      <div class=\"dval\">\r\n        <div><div class=\"k\">抽样次数<\/div><div class=\"v\" id=\"s-n\">2000<\/div><div class=\"s\">固定随机流 · 可复现<\/div><\/div>\r\n        <div><div class=\"k\">共同因子载荷<\/div><div class=\"v\" id=\"s-load\">0.60<\/div><div class=\"s\">z 空间两两相关 0.36<\/div><\/div>\r\n        <div><div class=\"k\">工序平均相关<\/div><div class=\"v\" id=\"s-corr\">—<\/div><div class=\"s\">2000 组实测<\/div><\/div>\r\n        <div><div class=\"k\">忽略相关<\/div><div class=\"v warn\" id=\"s-indep\">—<\/div><div class=\"s\">P10—P90 宽度会低估<\/div><\/div>\r\n      <\/div>\r\n      <div class=\"dfig-h\" style=\"margin-top:7px\"><b>工序分位（当前井）<\/b><span>天 · 按 P10 / P50 / P90<\/span><\/div>\r\n      <table class=\"dtable plantab\"><thead><tr><th>工序<\/th><th class=\"num\">P10<\/th><th class=\"num\">P50<\/th><th class=\"num\">P90<\/th><th class=\"num\">宽<\/th><\/tr><\/thead><tbody id=\"proc\"><\/tbody><\/table>\r\n      <div class=\"dfig-foot\" style=\"margin-top:5px\"><span id=\"key-hint\">—<\/span><\/div>\r\n    <\/div>\r\n\r\n    <div class=\"dfig dstage\" data-stage=\"4\">\r\n      <div class=\"dfig-h\"><b>05 · 计划决策与回写<\/b><span>分布 → 可承诺的日期<\/span><\/div>\r\n      <p class=\"dstage-lede\">计划工期是<b>承诺<\/b>，不是预测。滑杆给出「按 X 天报计划 → 按期概率 Y%」；P80 是常用承诺档，人工确认或改期后回写台账。<\/p>\r\n      <div class=\"dval\">\r\n        <div><div class=\"k\">当前计划<\/div><div class=\"v\" id=\"p-plan\">—<\/div><div class=\"s\">滑杆可调<\/div><\/div>\r\n        <div><div class=\"k\">按期概率<\/div><div class=\"v ok\" id=\"p-prob\">—<\/div><div class=\"s\">2000 次抽样中按时完工<\/div><\/div>\r\n        <div><div class=\"k\">P80 承诺<\/div><div class=\"v\" id=\"p-p80\">—<\/div><div class=\"s\">覆盖约 80% 抽样<\/div><\/div>\r\n        <div><div class=\"k\">关键工序<\/div><div class=\"v\" id=\"p-key\" style=\"font-size:11px\">—<\/div><div class=\"s\">方差贡献最大<\/div><\/div>\r\n      <\/div>\r\n      <table class=\"dtable plantab\" style=\"margin-top:7px\"><thead><tr><th>口径<\/th><th class=\"num\">工期<\/th><th class=\"num\">按期概率<\/th><\/tr><\/thead><tbody id=\"plantab\"><\/tbody><\/table>\r\n      <p class=\"mini\" style=\"margin-top:6px\">1450 井次 · 改造前后（示范口径，不是本页仿真读数）<\/p>\r\n      <table class=\"dtable valtab\"><thead><tr><th>指标<\/th><th>改造前<\/th><th>改造后<\/th><\/tr><\/thead><tbody>\r\n        <tr><td class=\"k2\">人工估工期 MAPE<\/td><td>28%<\/td><td class=\"up\">14%<\/td><\/tr>\r\n        <tr><td class=\"k2\">P80 承诺兑现率<\/td><td>62%<\/td><td class=\"up\">81%<\/td><\/tr>\r\n        <tr><td class=\"k2\">计划编制<\/td><td>2 h<\/td><td class=\"up\">10 min<\/td><\/tr>\r\n        <tr><td class=\"k2\">待机 / 窝工成本<\/td><td>基线<\/td><td class=\"up\">−18%<\/td><\/tr>\r\n      <\/tbody><\/table>\r\n      <div class=\"dfeed\" id=\"feedback\" style=\"margin-top:7px\">\r\n        <button class=\"dbtn\" type=\"button\" data-fb=\"adopt\">✓ 采纳 P80 承诺<\/button>\r\n        <button class=\"dbtn\" type=\"button\" data-fb=\"adjust\">✗ 人工上调 1 天<\/button>\r\n        <span class=\"dfeed-note\" id=\"fb-note\">回写 0 条 · 人工确认后才进入下一轮训练<\/span>\r\n      <\/div>\r\n    <\/div>\r\n\r\n    <div class=\"dmodel\">\r\n      <div class=\"dmodel-h\"><b>模型档案<\/b><span class=\"db plain\" id=\"m-badge\">已训练<\/span><\/div>\r\n      <div class=\"dmodel-row\"><span class=\"k\">任务<\/span><span class=\"v\">7 道工序 × P10/P50/P90 分位数回归 + 2000 次蒙特卡洛合成<\/span><\/div>\r\n      <div class=\"dmodel-row\"><span class=\"k\">数据<\/span><span class=\"v\">1450 井次合成工单 · 质控后 1322 · 80/20 划分<\/span><\/div>\r\n      <div class=\"dmodel-row\"><span class=\"k\">模型<\/span><span class=\"v\">21 组线性分位数回归 · 9 维特征 · pinball loss<\/span><\/div>\r\n      <div class=\"dmodel-row\"><span class=\"k\">验证<\/span><span class=\"v\" id=\"m-summary\">—<\/span><\/div>\r\n      <div class=\"dmodel-row\"><span class=\"k\">边界<\/span><span class=\"v\">工序口径不一致 / 截断工单 / 极端井况 → 区间变宽，转人工复核<\/span><\/div>\r\n    <\/div>\r\n\r\n    <div class=\"dfig\" style=\"padding-top:8px\">\r\n      <div class=\"dfig-h\"><b>过程日志<\/b><span>输入 → 处理 → 输出<\/span><\/div>\r\n      <div class=\"dtrace\" id=\"trace\"><\/div>\r\n    <\/div>\r\n  <\/div>\r\n<\/div>\r\n\r\n<p class=\"dnote\" id=\"note\"><\/p>\r\n\r\n<script src=\"demo.js\"><\/script>\r\n<\/body>\r\n<\/html>\r\n"}];
  var PKG = {"id":"workover-duration-ts","sceneId":"wo5","methods":["ts"],"title":"从历史工单到可承诺工期：分位数回归 + 蒙特卡洛","version":"2.0.0","updated":"2026-11-01","status":"ready","tabs":{"background":{"label":"专业背景","lede":"修井工期直接决定产量损失与作业队排班：一口井多停一天，少产几十吨油，影响的是整个区块的月度配产。但工期估计现在是「经验值」——同类作业在不同井上的实际工期可以差一倍，排班与物资准备因此经常失准；更麻烦的是不确定性无法表达：报 8 天，没人知道这是「大概率 7—9 天」还是「可能 5 天也可能 15 天」。落地时这条流水线分五段：**① 工单采集与质控**——1450 井次 × 7 道工序，先剔除异常、缺段、截断工单；**② 特征**——井深、故障类型 one-hot、复杂度、工序数、含打捞/套管等 9 维；**③ 分位数回归**——7 道工序 × P10/P50/P90 共 21 组线性模型，pinball loss 本页现场训练、留 20% 验证；**④ 蒙特卡洛合成**——按工序相关性抽 2000 次相加，得到总工期分布与按期概率；**⑤ 计划决策与回写**——计划工期滑杆、P80 承诺、人工调整回写。智能化不换数据源，只把「历史工单」变成「可承诺的日期」。","judge":[{"label":"任务类型","value":"分位数回归 + 蒙特卡洛","desc":"7 道工序 × 3 个分位，输出区间与按期概率——不是单点工期"},{"label":"数据门槛","value":"1000+ 井次工序级时效记录","desc":"井深、故障类型、7 道工序起止时间；缺工序或截断工单必须先剔除"},{"label":"可见收益","value":"P80 兑现率 62% → 81%","desc":"人工 MAPE 28% → 14%，计划编制 2 h → 10 min（示范口径）"},{"label":"难度","value":"中","desc":"工序口径统一与相关性建模是卡点，不是算法","html":"<span class='dtag' data-d='中'>难度 中<\/span>"}],"sections":[{"no":1,"en":"PROBLEM","title":"当前做法与问题","html":"<p>修井工期由一串工序串起来：起原井管柱 → 洗井 / 循环 → 打捞（或磨铣）→ 通井 → 下泵 → 试压 → 交井。每一道工序的耗时取决于井深、故障复杂度、管柱状况，还受天气、设备、队伍熟练度影响。现在的做法是拿邻井的「总工期」加一点经验余量，结果是：<b>有的井提前完工、队伍闲置；有的井严重超期、产量损失成倍<\/b>。<\/p><p>更麻烦的是<b>不确定性无法表达<\/b>。总工期报了 8 天，没人知道这是「大概率 7—9 天」还是「可能 5 天也可能 15 天」——而排班、车辆调度与配产需要的恰恰是后者。<\/p><div class='figure'><svg viewBox='0 0 660 220' xmlns='http://www.w3.org/2000/svg' role='img' aria-label='工期构成与不确定性'><text x='14' y='18' font-size='9.5' font-family='monospace' fill='#99a3a4' letter-spacing='1.2'>一口井的工期 = 7 道工序耗时之和，每一段都有不确定性<\/text><g font-size='9.5'><text x='14' y='44' fill='#4a585c'>起原井管柱<\/text><text x='14' y='68' fill='#4a585c'>洗井 / 循环<\/text><text x='14' y='92' fill='#4a585c'>打捞 / 磨铣<\/text><text x='14' y='116' fill='#4a585c'>通井<\/text><text x='14' y='140' fill='#4a585c'>下泵 / 下管柱<\/text><text x='14' y='164' fill='#4a585c'>试压<\/text><text x='14' y='188' fill='#4a585c'>交井 / 收尾<\/text><\/g><g><rect x='120' y='34' width='86' height='14' rx='3' fill='#1d4e50' opacity='.85'/><rect x='206' y='34' width='26' height='14' rx='3' fill='#1d4e50' opacity='.25'/><rect x='120' y='58' width='34' height='14' rx='3' fill='#1d4e50' opacity='.85'/><rect x='154' y='58' width='14' height='14' rx='3' fill='#1d4e50' opacity='.25'/><rect x='120' y='82' width='150' height='14' rx='3' fill='#1d4e50' opacity='.85'/><rect x='270' y='82' width='92' height='14' rx='3' fill='#1d4e50' opacity='.25'/><rect x='120' y='106' width='60' height='14' rx='3' fill='#1d4e50' opacity='.85'/><rect x='180' y='106' width='30' height='14' rx='3' fill='#1d4e50' opacity='.25'/><rect x='120' y='130' width='70' height='14' rx='3' fill='#1d4e50' opacity='.85'/><rect x='190' y='130' width='20' height='14' rx='3' fill='#1d4e50' opacity='.25'/><rect x='120' y='154' width='22' height='14' rx='3' fill='#1d4e50' opacity='.85'/><rect x='142' y='154' width='12' height='14' rx='3' fill='#1d4e50' opacity='.25'/><rect x='120' y='178' width='30' height='14' rx='3' fill='#1d4e50' opacity='.85'/><rect x='150' y='178' width='16' height='14' rx='3' fill='#1d4e50' opacity='.25'/><\/g><text x='430' y='54' font-size='10' fill='#123a3d'>深色 = P50（最可能的耗时）<\/text><text x='430' y='74' font-size='10' fill='#6f7a7c'>浅色 = P90 上限（保守估计）<\/text><text x='430' y='106' font-size='10' fill='#83551f'>打捞 / 磨铣 段最宽：<\/text><text x='430' y='124' font-size='10' fill='#83551f'>它贡献约 3/4 的总工期方差<\/text><text x='430' y='156' font-size='10' fill='#a64b3c'>经验法把这一段当成固定值，<\/text><text x='430' y='174' font-size='10' fill='#a64b3c'>于是总工期必然是错的<\/text><\/svg><\/div><div class='figcap'><b>图 1<\/b><span>注意「打捞 / 磨铣」这一段的区间宽度：它的不确定性远大于其他工序，因此它是<b>最不确定工序<\/b>（方差贡献最大）——把资源投在缩短它的不确定性上，比把每道工序都估准更有效。本示范默认井况下，它贡献约 77% 的总工期方差。<\/span><\/div>"},{"no":2,"en":"INTERVENTION","title":"AI 能做什么","html":"<p>五段流水线，每一段都很寻常，组合起来才解决「可承诺」的问题：<b>① 工单采集与质控<\/b>——1450 井次 × 7 道工序，剔除 47 条异常、51 条缺工序、30 条截断，剩 1322 条；<b>② 特征<\/b>——压成井深、5 类故障 one-hot、复杂度、工序数、含打捞/套管/磨铣/压井共 9 维；<b>③ 分位数回归<\/b>——7 道工序 × P10/P50/P90 共 21 组线性模型，pinball loss 现场训练、留 20% 验证，给出覆盖率与 P50 校准；<b>④ 蒙特卡洛合成<\/b>——每道工序按分位拟合对数正态，用共同因子保留工序相关性，抽 2000 次相加；<b>⑤ 计划决策与回写<\/b>——把分布翻译成「计划 X 天 → 按期 Y%」，按 P80 承诺，人工确认或改期后回写台账。<\/p><p>和「预测一个总工期数字」相比，这套做法的价值在于：<b>能回答排班真正关心的问题<\/b>——「按 10 天报计划，按期完工的概率是多少？」<\/p><div class='figure'><svg viewBox='0 0 660 230' xmlns='http://www.w3.org/2000/svg' role='img' aria-label='五段工期预测流水线'><text x='14' y='18' font-size='9.5' font-family='monospace' fill='#99a3a4' letter-spacing='1.2'>五段流水线：每一段都能在现场找到对应动作<\/text><g><rect x='7' y='32' width='118' height='78' rx='8' fill='#fdfcf9' stroke='#e3dccd'/><text x='66' y='52' font-size='10.5' fill='#4a585c' text-anchor='middle'>01 工单质控<\/text><text x='66' y='71' font-size='9' fill='#123a3d' text-anchor='middle'>1450 → 1322 条<\/text><text x='66' y='89' font-size='8.5' fill='#99a3a4' text-anchor='middle'>异常 / 缺段 / 截断<\/text><\/g><g><rect x='139' y='32' width='118' height='78' rx='8' fill='#fdfcf9' stroke='#e3dccd'/><text x='198' y='52' font-size='10.5' fill='#4a585c' text-anchor='middle'>02 特征<\/text><text x='198' y='71' font-size='9' fill='#123a3d' text-anchor='middle'>9 维井况特征<\/text><text x='198' y='89' font-size='8.5' fill='#99a3a4' text-anchor='middle'>井深 / 故障 / 复杂度<\/text><\/g><g><rect x='271' y='32' width='118' height='78' rx='8' fill='#e7eee9' stroke='#c8dbd2'/><text x='330' y='52' font-size='10.5' fill='#123a3d' text-anchor='middle'>03 分位数回归<\/text><text x='330' y='71' font-size='9' fill='#5f7d72' text-anchor='middle'>21 组模型<\/text><text x='330' y='89' font-size='8.5' fill='#5f7d72' text-anchor='middle'>P10 / P50 / P90<\/text><\/g><g><rect x='403' y='32' width='118' height='78' rx='8' fill='#e7eee9' stroke='#c8dbd2'/><text x='462' y='52' font-size='10.5' fill='#123a3d' text-anchor='middle'>04 蒙特卡洛<\/text><text x='462' y='71' font-size='9' fill='#5f7d72' text-anchor='middle'>2000 次抽样<\/text><text x='462' y='89' font-size='8.5' fill='#5f7d72' text-anchor='middle'>共同因子相关<\/text><\/g><g><rect x='535' y='32' width='118' height='78' rx='8' fill='#f4e8d4' stroke='#e3d3b4'/><text x='594' y='52' font-size='10.5' fill='#83551f' text-anchor='middle'>05 计划回写<\/text><text x='594' y='71' font-size='9' fill='#83551f' text-anchor='middle'>P80 承诺<\/text><text x='594' y='89' font-size='8.5' fill='#a07a44' text-anchor='middle'>人工调整回写<\/text><\/g><g stroke='#d3c9b6' stroke-width='1.4' fill='none'><path d='M126 71 L136 71'/><path d='M132 67 L137 71 L132 75 Z' fill='#d3c9b6'/><path d='M258 71 L268 71'/><path d='M264 67 L269 71 L264 75 Z' fill='#d3c9b6'/><path d='M390 71 L400 71'/><path d='M396 67 L401 71 L396 75 Z' fill='#d3c9b6'/><path d='M522 71 L532 71'/><path d='M528 67 L533 71 L528 75 Z' fill='#d3c9b6'/><\/g><path d='M594 112 L594 138 L66 138 L66 114' fill='none' stroke='#a9742c' stroke-width='1.2' stroke-dasharray='4 3'/><path d='M62 118 L66 112 L70 118 Z' fill='#a9742c'/><text x='330' y='154' font-size='9' fill='#83551f' text-anchor='middle'>人工确认 / 改期回写 → 下一轮重训<\/text><text x='14' y='184' font-size='10.5' fill='#4a585c'>P10 / P50 / P90 = 7.0 / 9.9 / 14.9 天 · 计划 10 天按期 51%<\/text><text x='14' y='208' font-size='10.5' fill='#123a3d'>P80 = 12.9 天覆盖约 80% · P80 兑现率 62% → 81%（示范口径）<\/text><\/svg><\/div><div class='figcap'><b>图 2<\/b><span>分位数回归与均值回归的区别只在损失函数：均值最小化平方误差，P90 最小化「低估的代价」。对工期这种<b>押错方向代价不对称<\/b>的问题，分位数比均值合适得多；而蒙特卡洛的作用是把 21 条工序曲线合成调度真正能用的「按期概率」。<\/span><\/div>"},{"no":3,"en":"DATA","title":"你需要准备什么","html":"<p>数据都在作业管理系统里，难点是<b>工序口径统一<\/b>：不同队伍对「洗井」的起止时间定义不同，有的把循环算进去、有的不算；有的把磨铣并进打捞、有的单列。这一步不统一，后面所有分位数都会失真。<\/p><div class='checklist'><div class='cl-head'><span>数据准备清单 · 4 项<\/span><span class='cl-prog'><span id='cl-txt'>0 / 4<\/span><span class='cl-bar'><i id='cl-fill'><\/i><\/span><\/span><\/div><div class='cl-item' data-cl='0'><span class='cl-box'><svg width='10' height='10' viewBox='0 0 24 24' fill='none' stroke='#fff' stroke-width='4' stroke-linecap='round' stroke-linejoin='round'><path d='M4 12.5l5 5L20 6.5'/><\/svg><\/span><span><span class='cl-t'>修井时效记录<\/span><span class='cl-s'>工序名称、起止时间、作业队<\/span><\/span><span class='cl-n'>1000+ 井次<\/span><\/div><div class='cl-item' data-cl='1'><span class='cl-box'><svg width='10' height='10' viewBox='0 0 24 24' fill='none' stroke='#fff' stroke-width='4' stroke-linecap='round' stroke-linejoin='round'><path d='M4 12.5l5 5L20 6.5'/><\/svg><\/span><span><span class='cl-t'>井况特征<\/span><span class='cl-s'>井深、故障类型、是否磨铣 / 压井<\/span><\/span><span class='cl-n'>作为回归自变量<\/span><\/div><div class='cl-item' data-cl='2'><span class='cl-box'><svg width='10' height='10' viewBox='0 0 24 24' fill='none' stroke='#fff' stroke-width='4' stroke-linecap='round' stroke-linejoin='round'><path d='M4 12.5l5 5L20 6.5'/><\/svg><\/span><span><span class='cl-t'>工序规范<\/span><span class='cl-s'>7 道标准工序的边界与包含范围<\/span><\/span><span class='cl-n'>口径统一的前提<\/span><\/div><div class='cl-item' data-cl='3'><span class='cl-box'><svg width='10' height='10' viewBox='0 0 24 24' fill='none' stroke='#fff' stroke-width='4' stroke-linecap='round' stroke-linejoin='round'><path d='M4 12.5l5 5L20 6.5'/><\/svg><\/span><span><span class='cl-t'>质量标记<\/span><span class='cl-s'>异常 / 缺段 / 截断工单的剔除规则<\/span><\/span><span class='cl-n'>质控门槛<\/span><\/div><\/div>"},{"no":4,"en":"DIFFICULTY","title":"技术难度与参考方向","html":"<div style='display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin-bottom:4px'><span class='dtag' data-d='中'>难度 中<\/span><span class='small muted'>方法成熟，卡点在数据口径、相关性建模与验收方式<\/span><\/div><div class='meter'><i class='on'><\/i><i class='on'><\/i><\/div><p>技术上不难：分位数回归用线性模型或梯度提升都能实现，蒙特卡洛只是相加。真正要做对的是三件事：<b>一<\/b>，工序口径统一（否则分位数没有意义）；<b>二<\/b>，工序间相关性——同一口井的打捞拖长，通井与下泵通常也会拖长，独立抽样会把总工期区间估窄；<b>三<\/b>，验收指标要选对：<b>不能用 MAE<\/b>（平均误差）衡量，而要用「P50 的绝对误差」+「P10—P90 区间的覆盖率」（区间应该覆盖约 80% 的实际值）。<\/p><p>另外两个细节：分位数交叉（P10 &gt; P50）在小样本工序上很常见，需要按分位顺序做单调性后处理；线性分位数回归对井深与故障类型的交互只能近似，现场数据量够时应换成梯度提升分位数回归，但验收口径不变。<\/p><p style='margin-top:18px'><span class='kicker plain' style='color:var(--ink-4)'>可借鉴的通用技术<\/span><\/p><div class='refs'><span class='ref'>分位数回归<\/span><span class='ref'>pinball loss<\/span><span class='ref'>蒙特卡洛模拟<\/span><span class='ref'>区间覆盖率评估<\/span><\/div><div class='callout'><span class='ci'>说明<\/span><span>这个场景很适合作为「不确定性建模」的入门案例：<b>把预测目标从点变成分布<\/b>，是整个石油行业智能化的一个共同升级方向——产量预测要区间、储量估算要区间、工期当然也要区间。<\/span><\/div>"}]},"workflow":{"label":"案例流程","title":"某修井公司 1450 井次时效数据的工期预测","lead":["改造前：调度按经验值排班，按期率 62%（三成以上的井超出计划工期），人工估工期 MAPE 28%。","改造后：每口井给出工序级 P10/P50/P90 + 总工期分布，调度按「计划 10 天 → 按期 51%」「P80 12.9 天 → 覆盖 80%」做承诺；P80 兑现率 81%（示范口径）。"],"stats":[["时效记录","1450 井次"],["工序数","7"],["验证覆盖","80.0%"],["P80 兑现率","62% → 81%"]],"steps":[{"name":"工单采集与质控","role":"数据","do":"从作业管理系统导出 1450 井次 × 7 道工序的时效记录，先过三道质控：耗时为负/为零或工序顺序异常（47 条）、7 道工序缺段（51 条）、总工期被系统在 2.6 天截断（30 条）。不合格工单既不进训练集，也不进验证集。","effect":"得到 1322 井次可用样本（91.2%），按 80/20 划分 1058 训练 / 264 验证。","trap":"截断工单最容易被忽略：系统在收尾时把总工期压到 2.6 天，如果留在训练集，模型会学会「所有井都很快」，P50 被系统性拉低。"},{"name":"特征：模型看到什么","role":"特征工程","do":"把每张工单压成 9 维：井深（km）、5 类故障 one-hot（落物打捞 / 套管整形 / 找堵水 / 冲砂防砂，断脱为基准）、作业复杂度（磨铣 0.6 + 压井 0.4）、工序数（7—9）、含打捞 / 套管 / 磨铣 / 压井。用训练集均值与标准差标准化。","effect":"模型能解释「同样的故障，深井为什么比浅井多 1—2 天」「磨铣与压井各把哪几道工序拉长」。","trap":"作业队、天气、设备型号不要直接进模型：它们会随台账变动，模型会突然失准；更稳的做法是分组建模或只用来做后校准。"},{"name":"工序级分位数回归","role":"算法核心","do":"对 7 道工序分别拟合 P10 / P50 / P90 三组线性分位数回归，损失函数是 pinball loss；特征标准化后梯度下降 200 轮，留出 264 井次验证。分位数交叉按单调性后处理，输出每道工序的区间。","effect":"21 组模型在本页现场训练：P10—P90 覆盖率 80.0%（名义 80%），P50 工序中位绝对误差 0.15 天，5 桶校准的预测/实际中位基本落在 45° 线上。","trap":"分位数交叉（P10 > P50）在小样本工序上很常见，必须做单调性后处理；另外线性模型对井深与故障的交互只能近似，别把系数当成因果效应。"},{"name":"蒙特卡洛合成总工期","role":"算法","do":"每道工序用 P10/P50/P90 拟合对数正态（σ = (lnP90 − lnP10) / 2.563），按工序依赖顺序抽 2000 组相加；工序之间用共同因子 z_p = 0.60·z₀ + 0.80·ε_p 保留相关性，z₀ 代表地层、队伍、设备的共同扰动。","effect":"输出总工期 P10 / P50 / P90、按期概率与方差贡献最大的工序；本示范默认井况 P50 = 9.9 天、P90 = 14.9 天，打捞/磨铣贡献约 77% 的方差。","trap":"忽略工序间相关性会低估总工期方差：本示范里独立抽样的 P10—P90 宽度只有 5.8 天，相关抽样是 7.8 天，覆盖率会从 80% 掉到 60% 以下。"},{"name":"计划决策与回写","role":"人工","do":"调度拖动计划工期滑杆，看「按 X 天报计划 → 按期 Y%」；常用 P80 作为承诺档，避免把 P50 当承诺。人工确认或改期后回写台账，下一轮重训进入训练集；每月统计实际落在区间内的比例与方差贡献最大的工序。","effect":"默认井况计划 10 天按期 51%，P80 = 12.9 天覆盖约 80%；现场口径 P80 兑现率 62% → 81%，计划编制 2 h → 10 min，待机/窝工成本 −18%（示范口径）。","trap":"只用「落在区间外」的井复盘不够，还要看「区间宽度是否随数据积累在收窄」——那才是模型真的在进步的证据；另外 P80 承诺兑现率要按同一口径统计，不能只挑顺利的井。"}],"metrics":{"title":"怎么算“做对了”","html":"<p>工期预测的指标和一般回归不一样：<b>不要用平均误差<\/b>，要看区间与概率。下表把<b>本页合成验证集<\/b>与<b>现场口径<\/b>分开列，两者不能混用。<\/p><table class='dtable'><thead><tr><th>指标<\/th><th>口径<\/th><th>取值<\/th><\/tr><\/thead><tbody><tr><td>P10—P90 覆盖率<\/td><td>本页合成验证集 · 264 井次 × 7 工序<\/td><td>80.0%（名义 80%）<\/td><\/tr><tr><td>P50 工序中位绝对误差<\/td><td>本页合成验证集<\/td><td>0.15 天<\/td><\/tr><tr><td>总工期 P50 中位绝对误差<\/td><td>本页合成验证集 · 含工单不可约波动<\/td><td>2.0 天<\/td><\/tr><tr><td>P50 校准（5 桶）<\/td><td>本页合成验证集<\/td><td>0.28/0.28 … 3.08/2.94 天<\/td><\/tr><tr><td>分位交叉<\/td><td>本页合成验证集 · 单调性后处理<\/td><td>0 条<\/td><\/tr><tr><td>人工估工期 MAPE<\/td><td>现场口径 · 1450 井次<\/td><td>28% → 14%（示范口径）<\/td><\/tr><tr><td>P80 承诺兑现率<\/td><td>现场口径<\/td><td>62% → 81%（示范口径）<\/td><\/tr><tr><td>计划编制<\/td><td>现场口径<\/td><td>2 h → 10 min（示范口径）<\/td><\/tr><tr><td>待机 / 窝工成本<\/td><td>现场口径<\/td><td>−18%（示范口径）<\/td><\/tr><\/tbody><\/table><p>P50 校准一行是 5 个桶的「预测中位 / 实际中位」，越接近 45° 线越好。<\/p><p>本示范默认井况（井深 2400 m、落物打捞、需磨铣与压井、计划 10 天）可复现：P10 / P50 / P90 = 7.0 / 9.9 / 14.9 天，计划 10 天的按期概率 51%，P80 = 12.9 天覆盖约 80%。覆盖率与宽度必须成对看：把区间拉宽到 20 天，覆盖率能到 99%，但那样的预测对排班毫无用处。<b>「覆盖 80% 且宽度尽量窄」才是目标<\/b>。<\/p>"},"fails":[{"name":"工序口径不统一","why":"同一道工序在不同队伍的记录里起止点不同，会把分布撑成双峰，模型学到的其实是「队伍习惯」而不是「工期规律」。"},{"name":"忽略工序间相关性","why":"独立抽样会让总工期区间过窄，覆盖率跌到 60% 以下；工序耗时之间存在明显的共同因素（地层、队伍、设备）。"},{"name":"把 P50 当承诺","why":"P50 只覆盖一半情形；按 P50 报计划，按期率天然只有 50% 左右。承诺应选 P80 或 P90，并明确对应的兑现率。"},{"name":"截断 / 缺段工单未剔除","why":"被系统截断的工单会把 P50 拉低，缺段工单会让工序分位数失真；质控不做，后面 21 组模型都在学错样本。"}]},"demo":{"mode":"auto","html":"demo/index.html","js":"demo/demo.js","label":"可运行示范","intro":"调井深、故障类型、磨铣/压井与计划工期，看五段流水线怎样从 1450 井次工单走到一条可承诺的日期：质控剔除 → 9 维特征 → 21 组分位数回归现场训练（损失曲线、P50 校准、P10—P90 覆盖）→ 2000 次蒙特卡洛合成 → 计划滑杆与 P80 承诺；再点「采纳 P80 承诺 / 人工上调 1 天」看回写怎么记。","height":1160}}};

  /* 供「案例包」页使用：在线试跑 + 一键下载 zip + 复制包结构 */
  var LIB = (window.CASE_PACKS = window.CASE_PACKS || {});
